const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  HeadingLevel, AlignmentType, BorderStyle, WidthType, ShadingType,
  LevelFormat, PageNumber, TabStopType, TabStopPosition
} = require('docx');
const fs = require('fs');

const BRAND_BLUE = "1A3A5C";
const BRAND_ACCENT = "2E86C1";
const LIGHT_BLUE = "D6EAF8";
const LIGHTER_BLUE = "EBF5FB";
const WHITE = "FFFFFF";
const DARK_GRAY = "2C3E50";

function h1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    spacing: { before: 360, after: 160 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: BRAND_ACCENT, space: 4 } },
    children: [new TextRun({ text, bold: true, size: 32, color: BRAND_BLUE, font: "Arial" })]
  });
}

function h2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    spacing: { before: 280, after: 120 },
    children: [new TextRun({ text, bold: true, size: 26, color: BRAND_ACCENT, font: "Arial" })]
  });
}

function h3(text) {
  return new Paragraph({
    spacing: { before: 200, after: 80 },
    children: [new TextRun({ text, bold: true, size: 22, color: DARK_GRAY, font: "Arial" })]
  });
}

function body(text, options = {}) {
  return new Paragraph({
    spacing: { before: 60, after: 60 },
    children: [new TextRun({ text, size: 20, font: "Arial", color: "2C3E50", ...options })]
  });
}

function bullet(text, bold = false) {
  return new Paragraph({
    numbering: { reference: "bullets", level: 0 },
    spacing: { before: 40, after: 40 },
    children: [new TextRun({ text, size: 20, font: "Arial", color: "2C3E50", bold })]
  });
}

function spacer() {
  return new Paragraph({ spacing: { before: 100, after: 100 }, children: [new TextRun("")] });
}

function calloutBox(title, content, fillColor = LIGHT_BLUE) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [
      new TableRow({
        children: [new TableCell({
          shading: { fill: fillColor, type: ShadingType.CLEAR },
          borders: {
            top: { style: BorderStyle.SINGLE, size: 4, color: BRAND_ACCENT },
            bottom: { style: BorderStyle.SINGLE, size: 1, color: "AAAAAA" },
            left: { style: BorderStyle.SINGLE, size: 4, color: BRAND_ACCENT },
            right: { style: BorderStyle.SINGLE, size: 1, color: "AAAAAA" },
          },
          margins: { top: 120, bottom: 120, left: 200, right: 200 },
          width: { size: 9360, type: WidthType.DXA },
          children: [
            new Paragraph({
              children: [new TextRun({ text: title, bold: true, size: 22, color: BRAND_BLUE, font: "Arial" })]
            }),
            new Paragraph({
              spacing: { before: 60 },
              children: [new TextRun({ text: content, size: 20, font: "Arial", color: "2C3E50" })]
            })
          ]
        })]
      })
    ]
  });
}

function ideaCard(number, title, tagline, description, aiAngle, revenuePotential, difficulty) {
  const rows = [];

  // Header row
  rows.push(new TableRow({
    children: [new TableCell({
      columnSpan: 2,
      shading: { fill: BRAND_BLUE, type: ShadingType.CLEAR },
      borders: { top: { style: BorderStyle.NONE }, bottom: { style: BorderStyle.NONE }, left: { style: BorderStyle.NONE }, right: { style: BorderStyle.NONE } },
      margins: { top: 120, bottom: 80, left: 200, right: 200 },
      width: { size: 9360, type: WidthType.DXA },
      children: [
        new Paragraph({
          children: [
            new TextRun({ text: `#${number}  `, bold: true, size: 28, color: "7FB3D3", font: "Arial" }),
            new TextRun({ text: title, bold: true, size: 28, color: WHITE, font: "Arial" }),
          ]
        }),
        new Paragraph({
          children: [new TextRun({ text: tagline, size: 20, color: "AED6F1", font: "Arial", italics: true })]
        })
      ]
    })]
  }));

  // Content row
  rows.push(new TableRow({
    children: [
      new TableCell({
        shading: { fill: LIGHTER_BLUE, type: ShadingType.CLEAR },
        borders: { top: { style: BorderStyle.NONE }, bottom: { style: BorderStyle.SINGLE, size: 2, color: "CCCCCC" }, left: { style: BorderStyle.NONE }, right: { style: BorderStyle.SINGLE, size: 1, color: "CCCCCC" } },
        margins: { top: 120, bottom: 120, left: 200, right: 200 },
        width: { size: 5760, type: WidthType.DXA },
        children: [
          new Paragraph({ children: [new TextRun({ text: "The Concept", bold: true, size: 18, color: BRAND_BLUE, font: "Arial" })] }),
          new Paragraph({ spacing: { before: 60 }, children: [new TextRun({ text: description, size: 19, font: "Arial", color: "2C3E50" })] }),
          spacer(),
          new Paragraph({ children: [new TextRun({ text: "🤖 AI Advantage", bold: true, size: 18, color: BRAND_BLUE, font: "Arial" })] }),
          new Paragraph({ spacing: { before: 60 }, children: [new TextRun({ text: aiAngle, size: 19, font: "Arial", color: "2C3E50" })] }),
        ]
      }),
      new TableCell({
        shading: { fill: WHITE, type: ShadingType.CLEAR },
        borders: { top: { style: BorderStyle.NONE }, bottom: { style: BorderStyle.SINGLE, size: 2, color: "CCCCCC" }, left: { style: BorderStyle.NONE }, right: { style: BorderStyle.NONE } },
        margins: { top: 120, bottom: 120, left: 200, right: 200 },
        width: { size: 3600, type: WidthType.DXA },
        children: [
          new Paragraph({ children: [new TextRun({ text: "Revenue Potential", bold: true, size: 18, color: BRAND_BLUE, font: "Arial" })] }),
          new Paragraph({ spacing: { before: 60 }, children: [new TextRun({ text: revenuePotential, size: 19, font: "Arial", color: "2C3E50" })] }),
          spacer(),
          new Paragraph({ children: [new TextRun({ text: "Launch Complexity", bold: true, size: 18, color: BRAND_BLUE, font: "Arial" })] }),
          new Paragraph({ spacing: { before: 60 }, children: [new TextRun({ text: difficulty, size: 19, font: "Arial", color: "2C3E50" })] }),
        ]
      })
    ]
  }));

  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [5760, 3600],
    rows
  });
}

const doc = new Document({
  numbering: {
    config: [
      {
        reference: "bullets",
        levels: [{ level: 0, format: LevelFormat.BULLET, text: "•", alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 720, hanging: 360 } } } }]
      }
    ]
  },
  styles: {
    default: { document: { run: { font: "Arial", size: 20 } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true, run: { size: 32, bold: true, font: "Arial" }, paragraph: { spacing: { before: 240, after: 240 }, outlineLevel: 0 } },
      { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true, run: { size: 26, bold: true, font: "Arial" }, paragraph: { spacing: { before: 180, after: 120 }, outlineLevel: 1 } },
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 }
      }
    },
    children: [
      // ─── COVER ───
      new Paragraph({ spacing: { before: 600, after: 200 }, alignment: AlignmentType.CENTER, children: [new TextRun({ text: "OPIN CAR MACHINERY", bold: true, size: 52, color: BRAND_BLUE, font: "Arial" })] }),
      new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "AI-Powered Business Expansion", size: 34, color: BRAND_ACCENT, font: "Arial", italics: true })] }),
      new Paragraph({ spacing: { before: 60, after: 400 }, alignment: AlignmentType.CENTER, children: [new TextRun({ text: "Strategic Brainstorm for TJ  ·  February 2026", size: 22, color: "888888", font: "Arial" })] }),

      new Table({
        width: { size: 9360, type: WidthType.DXA },
        columnWidths: [9360],
        rows: [new TableRow({
          children: [new TableCell({
            shading: { fill: BRAND_BLUE, type: ShadingType.CLEAR },
            borders: { top: { style: BorderStyle.NONE }, bottom: { style: BorderStyle.NONE }, left: { style: BorderStyle.NONE }, right: { style: BorderStyle.NONE } },
            margins: { top: 200, bottom: 200, left: 360, right: 360 },
            width: { size: 9360, type: WidthType.DXA },
            children: [
              new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "You've already built a great machine business.", bold: true, size: 26, color: WHITE, font: "Arial" })] }),
              new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 80 }, children: [new TextRun({ text: "These ideas are designed to leverage your existing equipment expertise, client relationships, and industry credibility — while adding smart AI-powered layers that create recurring revenue and competitive separation.", size: 20, color: "AED6F1", font: "Arial" })] })
            ]
          })]
        })]
      }),

      spacer(),
      spacer(),

      // ─── INTRO ───
      h1("The Opportunity"),
      body("Opin Car Machinery sits in a powerful position: you know the equipment, you know the industry, and you likely have the trust of shop owners, dealerships, and fleet operators who are begging for smarter ways to run their businesses. AI is finally accessible enough to bolt onto what you've already built — without needing to become a tech company."),
      spacer(),
      body("Below are six high-potential side business ideas, each designed around your core strengths and real market demand in the automotive machinery space."),
      spacer(),
      spacer(),

      // ─── IDEA 1 ───
      h1("The Ideas"),
      spacer(),

      ideaCard(
        "01",
        "AI-Powered Equipment Maintenance Subscription",
        "Predictive maintenance as a monthly service — before things break.",
        "Create a subscription service where you install low-cost IoT sensors on the machinery you sell (or sold). AI analyzes usage patterns and sends automated alerts to shop owners before equipment fails. You become the proactive maintenance partner rather than the reactive repair call.",
        "AI monitoring dashboards, automated SMS/email alerts, predictive scheduling for your service team. Integrations with platforms like Uptake, SparkCognition, or a custom-built AI dashboard are now affordable even for small operators.",
        "$199–$499/month per location. With 50 clients that's $10K–$25K MRR with minimal overhead once the system is running.",
        "Medium. Requires IoT sensor sourcing and a simple dashboard build. Many white-label platforms exist. Could launch an MVP in 60–90 days."
      ),
      spacer(),
      spacer(),

      ideaCard(
        "02",
        "AutoShop AI Consultant (Done-For-You AI Setup)",
        "Helping shops implement AI without the tech headache.",
        "Most independent auto shops and car washes have no idea how to use AI to save money or grow. You're perfectly positioned to offer a 'Done For You' AI implementation service — setting up AI scheduling, customer follow-up automation, inventory tracking, and marketing tools. TJ becomes the trusted tech guide for a non-tech audience.",
        "You'd use tools like Make.com, Go High Level, and AI chatbots to automate shop operations. You don't need to build anything — you configure and deploy existing tools. Pair with an AI chatbot for customer intake and after-hours quote requests.",
        "Flat setup fee of $3,000–$8,000 + $500–$1,000/month retainer. 10 retained clients = $5K–$10K/month passive.",
        "Low-Medium. Your industry knowledge is the unfair advantage. The tools already exist — you just need to learn the configurations or partner with a tech VA."
      ),
      spacer(),
      spacer(),

      ideaCard(
        "03",
        "Machinery Resale + AI-Graded Inspection Reports",
        "Used equipment with a trusted, data-backed grade — like Carfax for machines.",
        "Build a premium used machinery resale operation where every machine sold comes with an AI-assisted condition report, video walkthrough, and digital inspection PDF. Buyers trust you more. You can charge more. Stand out from every other used equipment seller online.",
        "Use AI vision tools to help score machine condition from video/photo uploads. Generate automated inspection reports with AI-written summaries. Publish listings with QR codes that link to the AI-graded report. This is still virtually untouched in the auto machinery resale market.",
        "Higher margins on resale (10–20% premium for certified/graded machines). Potential to build a marketplace or affiliate program. Subscription for dealers who want the grading service: $300–$600/month.",
        "Low. Build on what you already do. Add an inspection template, record video walkthroughs, use ChatGPT to auto-generate the report narrative. Very few upfront costs."
      ),
      spacer(),
      spacer(),

      ideaCard(
        "04",
        "AI Training Academy for Shop Technicians",
        "Online courses that teach automotive techs how to use AI on the shop floor.",
        "Launch a digital training platform — video courses + live workshops — teaching shop technicians, service advisors, and shop owners how to use AI tools in their day-to-day work. Topics: AI diagnostics, automated customer communication, inventory AI, AI marketing for shops. Sell as self-paced courses or live cohort programs.",
        "Courses built with AI tools (Synthesia for video, ChatGPT for scripts, Teachable/Kajabi for delivery). AI-personalized learning paths based on the student's shop type. This mirrors what your consulting partner Bethany has done with Youthtopia — CE-accredited training is a strong model.",
        "$97–$497 per course. Cohort programs at $1,500–$3,000. 100 students/month = $10K–$50K depending on program mix. Highly scalable — record once, sell forever.",
        "Medium. Recording and editing takes time upfront. Revenue grows slowly then compounds. Excellent long-term brand builder and lead gen for higher-ticket services."
      ),
      spacer(),
      spacer(),

      ideaCard(
        "05",
        "Fleet & Dealership AI Operations Audit",
        "A one-time premium service with ongoing upsell potential.",
        "Offer a comprehensive AI Operations Audit for automotive dealerships, fleet management companies, and large car washes/detail shops. Spend 2–3 days on-site (or virtually), document their current workflow, identify AI implementation opportunities, and deliver a detailed roadmap report. High-ticket, minimal overhead, leverages your credibility.",
        "Use AI tools to auto-generate parts of the audit report from your notes. AI-assisted competitor benchmarking, operational gap analysis, and ROI projections included in every report. The audit itself becomes a lead magnet for your ongoing subscription services.",
        "$5,000–$15,000 per audit depending on business size. Upsell into implementation retainers. Just 3 audits per month = $15K–$45K revenue. Very high margin.",
        "Low. This is a consulting play — your expertise IS the product. Needs a solid audit template and report format. Build once, reuse forever."
      ),
      spacer(),
      spacer(),

      ideaCard(
        "06",
        "AI-Powered Parts & Inventory Procurement Platform",
        "The smarter way for shops to buy the right parts at the right price.",
        "Build or white-label a platform that helps independent auto shops manage parts inventory with AI — predicting what parts they'll need based on historical data, flagging price anomalies, and auto-generating purchase orders. Position yourself as the technology middleman between shops and suppliers, taking a referral or SaaS fee.",
        "Partner with existing parts distributors and earn a referral/affiliate margin. The AI layer (demand forecasting, reorder triggers, pricing alerts) is the value-add that justifies your platform fee. Tools like Partly, PartsTech, or custom-built with AI APIs can form the backbone.",
        "$299–$799/month SaaS fee per shop. Referral margin from parts suppliers (5–15%). Significant upside if you build a marketplace with 50+ shops. Larger capital investment but high barrier to entry once built.",
        "High. This is a more complex build and requires supplier relationships. Best pursued after establishing cash flow with simpler offerings above. Could be a 12–18 month build."
      ),

      spacer(),
      spacer(),

      // ─── PRIORITY MATRIX ───
      h1("Where to Start: Priority Recommendation"),
      spacer(),

      new Table({
        width: { size: 9360, type: WidthType.DXA },
        columnWidths: [2200, 2500, 2500, 2160],
        rows: [
          new TableRow({
            children: [
              new TableCell({
                shading: { fill: BRAND_BLUE, type: ShadingType.CLEAR },
                borders: { top: { style: BorderStyle.NONE }, bottom: { style: BorderStyle.NONE }, left: { style: BorderStyle.NONE }, right: { style: BorderStyle.NONE } },
                margins: { top: 100, bottom: 100, left: 120, right: 120 },
                width: { size: 2200, type: WidthType.DXA },
                children: [new Paragraph({ children: [new TextRun({ text: "Idea", bold: true, size: 20, color: WHITE, font: "Arial" })] })]
              }),
              new TableCell({
                shading: { fill: BRAND_BLUE, type: ShadingType.CLEAR },
                borders: { top: { style: BorderStyle.NONE }, bottom: { style: BorderStyle.NONE }, left: { style: BorderStyle.NONE }, right: { style: BorderStyle.NONE } },
                margins: { top: 100, bottom: 100, left: 120, right: 120 },
                width: { size: 2500, type: WidthType.DXA },
                children: [new Paragraph({ children: [new TextRun({ text: "Speed to Revenue", bold: true, size: 20, color: WHITE, font: "Arial" })] })]
              }),
              new TableCell({
                shading: { fill: BRAND_BLUE, type: ShadingType.CLEAR },
                borders: { top: { style: BorderStyle.NONE }, bottom: { style: BorderStyle.NONE }, left: { style: BorderStyle.NONE }, right: { style: BorderStyle.NONE } },
                margins: { top: 100, bottom: 100, left: 120, right: 120 },
                width: { size: 2500, type: WidthType.DXA },
                children: [new Paragraph({ children: [new TextRun({ text: "Scalability", bold: true, size: 20, color: WHITE, font: "Arial" })] })]
              }),
              new TableCell({
                shading: { fill: BRAND_BLUE, type: ShadingType.CLEAR },
                borders: { top: { style: BorderStyle.NONE }, bottom: { style: BorderStyle.NONE }, left: { style: BorderStyle.NONE }, right: { style: BorderStyle.NONE } },
                margins: { top: 100, bottom: 100, left: 120, right: 120 },
                width: { size: 2160, type: WidthType.DXA },
                children: [new Paragraph({ children: [new TextRun({ text: "Best For", bold: true, size: 20, color: WHITE, font: "Arial" })] })]
              }),
            ]
          }),
          ...[
            ["AI Ops Audit", "⚡ Fastest (weeks)", "★★★☆ Good", "Immediate cash"],
            ["AI-Graded Resale", "⚡ Fast (1–2 months)", "★★★☆ Good", "Margin boost"],
            ["AutoShop AI Consult", "⚡ Fast (1–2 months)", "★★★★ High", "Recurring revenue"],
            ["Maintenance Sub.", "Medium (3–4 months)", "★★★★ High", "MRR growth"],
            ["AI Training Academy", "Slow build (6 months)", "★★★★★ Best", "Passive income"],
            ["Parts Platform", "Long (12–18 months)", "★★★★★ Best", "Long-term play"],
          ].map((row, i) =>
            new TableRow({
              children: row.map((cell, j) =>
                new TableCell({
                  shading: { fill: i % 2 === 0 ? LIGHTER_BLUE : WHITE, type: ShadingType.CLEAR },
                  borders: { top: { style: BorderStyle.SINGLE, size: 1, color: "CCCCCC" }, bottom: { style: BorderStyle.SINGLE, size: 1, color: "CCCCCC" }, left: { style: BorderStyle.NONE }, right: { style: BorderStyle.NONE } },
                  margins: { top: 80, bottom: 80, left: 120, right: 120 },
                  width: { size: [2200, 2500, 2500, 2160][j], type: WidthType.DXA },
                  children: [new Paragraph({ children: [new TextRun({ text: cell, size: 19, font: "Arial", color: "2C3E50", bold: j === 0 })] })]
                })
              )
            })
          )
        ]
      }),

      spacer(),
      spacer(),

      // ─── TJ'S UNFAIR ADVANTAGE ───
      h1("TJ's Unfair Advantages"),
      spacer(),
      calloutBox(
        "Why This Works for You Specifically",
        "You already have the hardest part: industry credibility and existing client relationships. Every shop owner, dealership, or fleet operator who has bought from Opin Car Machinery already trusts you. You're not starting from zero — you're expanding from a position of authority."
      ),
      spacer(),
      body("Here's what makes TJ uniquely positioned to win in this space:"),
      bullet("Equipment expertise that tech-only consultants can never replicate"),
      bullet("Existing client base = warm market for the first sales conversations"),
      bullet("AI tools are now low-code/no-code — you don't need developers to start"),
      bullet("The automotive industry is still early in AI adoption — first-mover advantage is real"),
      bullet("Your sales background gives you the ability to close these deals in a conversation"),

      spacer(),
      spacer(),

      // ─── NEXT STEPS ───
      h1("Suggested 90-Day Launch Path"),
      spacer(),
      h3("Month 1 — Validate & Sell"),
      bullet("Pick one idea (recommend: AI Ops Audit or AI-Graded Resale)"),
      bullet("Have 10 conversations with existing Opin clients or prospects about the concept"),
      bullet("Sell 2–3 engagements before building anything — confirm real demand first"),
      spacer(),

      h3("Month 2 — Build Minimally"),
      bullet("Create your audit template, report template, or inspection checklist"),
      bullet("Set up basic automation using Make.com or Go High Level"),
      bullet("Deliver your first 2–3 paying clients and document what works"),
      spacer(),

      h3("Month 3 — Productize & Promote"),
      bullet("Build a simple landing page and case study from early wins"),
      bullet("Begin LinkedIn content strategy positioning TJ as the 'AI + Auto Machinery' expert"),
      bullet("Launch referral program with existing Opin Machinery clients"),

      spacer(),
      spacer(),

      // ─── FOOTER NOTE ───
      new Table({
        width: { size: 9360, type: WidthType.DXA },
        columnWidths: [9360],
        rows: [new TableRow({
          children: [new TableCell({
            shading: { fill: DARK_GRAY, type: ShadingType.CLEAR },
            borders: { top: { style: BorderStyle.NONE }, bottom: { style: BorderStyle.NONE }, left: { style: BorderStyle.NONE }, right: { style: BorderStyle.NONE } },
            margins: { top: 160, bottom: 160, left: 360, right: 360 },
            width: { size: 9360, type: WidthType.DXA },
            children: [
              new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "The best time to add an AI-powered revenue stream was 2023. The second best time is now.", bold: true, size: 22, color: WHITE, font: "Arial", italics: true })] }),
              new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 80 }, children: [new TextRun({ text: "Prepared exclusively for TJ · Opin Car Machinery · February 2026", size: 18, color: "AAAAAA", font: "Arial" })] })
            ]
          })]
        })]
      }),
    ]
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync('/home/claude/opin_ai_brainstorm.docx', buffer);
  console.log('Done!');
});

