const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  HeadingLevel, AlignmentType, BorderStyle, WidthType, ShadingType,
  LevelFormat, PageBreak
} = require('docx');
const fs = require('fs');

const BRAND_NAVY   = "1C2B4A";
const BRAND_STEEL  = "2E6DA4";
const BRAND_GOLD   = "C9922A";
const LIGHT_STEEL  = "D9E8F5";
const LIGHTER_STEEL= "EEF5FB";
const OFF_WHITE    = "F8FAFB";
const WHITE        = "FFFFFF";
const DARK         = "1E1E1E";

const border = (color = "CCCCCC") => ({ style: BorderStyle.SINGLE, size: 1, color });
const noBorder = () => ({ style: BorderStyle.NONE, size: 0, color: "FFFFFF" });
const allNone = { top: noBorder(), bottom: noBorder(), left: noBorder(), right: noBorder() };
const allGray = { top: border(), bottom: border(), left: border(), right: border() };

function para(children, opts = {}) {
  return new Paragraph({ children, ...opts });
}

function run(text, opts = {}) {
  return new TextRun({ text, font: "Arial", ...opts });
}

function h1(text) {
  return new Paragraph({
    spacing: { before: 360, after: 120 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 8, color: BRAND_GOLD, space: 4 } },
    children: [run(text, { bold: true, size: 34, color: BRAND_NAVY })]
  });
}

function h2(text) {
  return new Paragraph({
    spacing: { before: 240, after: 100 },
    children: [run(text, { bold: true, size: 26, color: BRAND_STEEL })]
  });
}

function h3(text) {
  return new Paragraph({
    spacing: { before: 180, after: 80 },
    children: [run(text, { bold: true, size: 22, color: BRAND_NAVY })]
  });
}

function body(text, opts = {}) {
  return new Paragraph({
    spacing: { before: 60, after: 80 },
    children: [run(text, { size: 20, color: "2C3E50", ...opts })]
  });
}

function bulletItem(text, bold = false) {
  return new Paragraph({
    numbering: { reference: "bullets", level: 0 },
    spacing: { before: 40, after: 40 },
    children: [run(text, { size: 20, color: "2C3E50", bold })]
  });
}

function spacer(sz = 100) {
  return new Paragraph({ spacing: { before: sz, after: sz }, children: [run("")] });
}

function cell(children, width, fill = WHITE, borders = allGray, marginOverride = null) {
  return new TableCell({
    shading: { fill, type: ShadingType.CLEAR },
    borders,
    margins: marginOverride || { top: 120, bottom: 120, left: 180, right: 180 },
    width: { size: width, type: WidthType.DXA },
    children: Array.isArray(children) ? children : [children]
  });
}

function headerCell(text, width) {
  return cell(
    [para([run(text, { bold: true, size: 20, color: WHITE })])],
    width,
    BRAND_NAVY,
    allNone
  );
}

function bannerBox(line1, line2, fill = BRAND_NAVY) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [new TableRow({ children: [
      cell([
        para([run(line1, { bold: true, size: 28, color: WHITE })], { alignment: AlignmentType.CENTER }),
        para([run(line2, { size: 20, color: "B8CCE4", italics: true })], { alignment: AlignmentType.CENTER, spacing: { before: 80 } })
      ], 9360, fill, allNone, { top: 200, bottom: 200, left: 400, right: 400 })
    ]})]
  });
}

// ─── IDEA CARD ──────────────────────────────────────────────────────────────
function ideaCard(num, title, tagline, concept, aiLayer, revenue, complexity, timing) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [
      // Title row
      new TableRow({ children: [
        cell([
          para([
            run(`IDEA #${num}  ·  `, { bold: true, size: 22, color: BRAND_GOLD }),
            run(title, { bold: true, size: 26, color: WHITE })
          ]),
          para([run(tagline, { size: 19, color: "AAC8E8", italics: true })], { spacing: { before: 60 } })
        ], 9360, BRAND_NAVY, allNone, { top: 160, bottom: 120, left: 280, right: 280 })
      ]}),

      // Two-column body
      new TableRow({ children: [
        new TableCell({
          shading: { fill: LIGHTER_STEEL, type: ShadingType.CLEAR },
          borders: { top: noBorder(), bottom: border("BBBBBB"), left: noBorder(), right: border("CCCCCC") },
          margins: { top: 160, bottom: 160, left: 280, right: 280 },
          width: { size: 9360, type: WidthType.DXA },
          children: [
            // 2-col inner layout via table
            new Table({
              width: { size: 8800, type: WidthType.DXA },
              columnWidths: [5200, 3600],
              rows: [new TableRow({ children: [
                // Left col
                new TableCell({
                  shading: { fill: LIGHTER_STEEL, type: ShadingType.CLEAR },
                  borders: { top: noBorder(), bottom: noBorder(), left: noBorder(), right: border("DDDDDD") },
                  margins: { top: 0, bottom: 0, left: 0, right: 200 },
                  width: { size: 5200, type: WidthType.DXA },
                  children: [
                    para([run("THE CONCEPT", { bold: true, size: 17, color: BRAND_STEEL })]),
                    para([run(concept, { size: 19, color: DARK })], { spacing: { before: 60, after: 120 } }),
                    para([run("🤖  AI LAYER", { bold: true, size: 17, color: BRAND_STEEL })]),
                    para([run(aiLayer, { size: 19, color: DARK })], { spacing: { before: 60 } }),
                  ]
                }),
                // Right col
                new TableCell({
                  shading: { fill: OFF_WHITE, type: ShadingType.CLEAR },
                  borders: allNone,
