                })
              ]})]
            })
          ]
        })
      ]})
    ]
  });
}

// ─── MATRIX TABLE ────────────────────────────────────────────────────────────
function matrixTable(rows) {
  const cols = [2800, 1880, 1880, 1560, 1240];
