const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  HeadingLevel, AlignmentType, BorderStyle, WidthType, ShadingType,
  LevelFormat, PageBreak
} = require('docx');
const fs = require('fs');

// ── COLORS ───────────────────────────────────────────────────────────────────
const NAVY    = "1C2B4A";
const STEEL   = "2E6DA4";
const GOLD    = "C9922A";
const GREEN   = "1E6B3C";
const RED     = "8B1A1A";
const LT_BLUE = "D9E8F5";
const LT_GRN  = "D5EEE0";
const LT_GOLD = "FAF0DC";
const LT_GRAY = "F2F4F6";
const OFFWHT  = "FAFBFC";
const WHITE   = "FFFFFF";
const DARK    = "1E2A35";

// ── HELPERS ──────────────────────────────────────────────────────────────────
const nb = () => ({ style: BorderStyle.NONE, size: 0, color: WHITE });
const sb = (c="CCCCCC",sz=1) => ({ style: BorderStyle.SINGLE, size: sz, color: c });
const allNone = { top: nb(), bottom: nb(), left: nb(), right: nb() };
const allGray = { top: sb(), bottom: sb(), left: sb(), right: sb() };
const bottomOnly = (c="CCCCCC") => ({ top: nb(), bottom: sb(c,2), left: nb(), right: nb() });
const topBottom = (c="CCCCCC") => ({ top: sb(c), bottom: sb(c), left: nb(), right: nb() });

function r(text, opts={}) {
  return new TextRun({ text, font: "Arial", ...opts });
}
function p(children, opts={}) {
  return new Paragraph({ children: Array.isArray(children) ? children : [r(children, {size:20,color:DARK})], ...opts });
}
function spacer(sz=120) {
  return new Paragraph({ spacing:{before:sz,after:sz}, children:[r("")] });
}
function bullet(text, color=DARK, bold=false, level=0) {
  return new Paragraph({
    numbering: { reference: level===0?"bullets":"bullets2", level: 0 },
    spacing: { before: 50, after: 50 },
    children: [r(text, { size: 20, color, bold })]
  });
}
function numberedItem(text, ref="numbers") {
  return new Paragraph({
    numbering: { reference: ref, level: 0 },
    spacing: { before: 60, after: 60 },
    children: [r(text, { size: 20, color: DARK })]
  });
}

function singleColTable(children, fill, borders, margins={ top:160, bottom:160, left:240, right:240 }) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [new TableRow({ children: [new TableCell({
      shading: { fill, type: ShadingType.CLEAR },
      borders,
      margins,
      width: { size: 9360, type: WidthType.DXA },
      children
    })] })]
  });
}

function twoColTable(leftChildren, rightChildren, leftWidth, rightWidth, fill=OFFWHT) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [leftWidth, rightWidth],
    rows: [new TableRow({ children: [
      new TableCell({
        shading: { fill, type: ShadingType.CLEAR },
        borders: { top:nb(), bottom:nb(), left:nb(), right:sb("DDDDDD") },
        margins: { top:140, bottom:140, left:220, right:220 },
        width: { size: leftWidth, type: WidthType.DXA },
        children: leftChildren
      }),
      new TableCell({
        shading: { fill: WHITE, type: ShadingType.CLEAR },
        borders: { top:nb(), bottom:nb(), left:nb(), right:nb() },
        margins: { top:140, bottom:140, left:220, right:220 },
        width: { size: rightWidth, type: WidthType.DXA },
        children: rightChildren
      })
    ]})]
  });
}

// ── SECTION BUILDERS ─────────────────────────────────────────────────────────

function coverPage() {
  return [
    spacer(500),
    p([r("OPINCAR MACHINERY", { bold:true, size:56, color:NAVY })], { alignment: AlignmentType.CENTER }),
    p([r("Sales & Marketing Playbook", { size:34, color:STEEL, italics:true })], { alignment: AlignmentType.CENTER, spacing:{before:80} }),
    p([r("How to Present and Sell Each AI-Powered Service  ·  February 2026", { size:20, color:"888888" })], { alignment: AlignmentType.CENTER, spacing:{before:60,after:500} }),
    singleColTable([
      p([r("Six ready-to-execute business ideas. For each one: who to call, what to say, how to get in the room, and exactly how to market to industrial buyers who don't live on social media.", { size:21, color:WHITE })], { alignment:AlignmentType.CENTER }),
    ], NAVY, allNone, { top:220, bottom:220, left:400, right:400 }),
    spacer(300),
    p([r("Contents at a Glance", { bold:true, size:22, color:NAVY })]),
    spacer(40),
    ...[
      "Idea #01  —  AI-Powered CNC Machine Valuation Service",
      "Idea #02  —  Condition Intelligence Reports on Every Listing",
      "Idea #03  —  Plant Decommission & AI Asset Inventory Service",
      "Idea #04  —  CNC Machinery Sourcing Subscription",
      "Idea #05  —  Rigging & Relocation Estimating Tool",
      "Idea #06  —  Industrial Auction Intelligence Advisory",
    ].map((line, i) => p([
      r(`${i+1}.  `, { bold:true, size:20, color:GOLD }),
      r(line, { size:20, color:DARK })
    ], { spacing:{before:60,after:60} })),
  ];
}

function pageBreak() {
  return new Paragraph({ children: [new TextRun({ break: 1 })] });
}

function ideaHeader(num, title, subtitle) {
  return singleColTable([
    p([r(`IDEA #${num}`, { bold:true, size:20, color:GOLD })]),
    p([r(title, { bold:true, size:34, color:WHITE })], { spacing:{before:60} }),
    p([r(subtitle, { size:20, color:"AAC8E8", italics:true })], { spacing:{before:80} }),
  ], NAVY, allNone, { top:200, bottom:200, left:280, right:280 });
}

function sectionLabel(label, fill=LT_BLUE, textColor=NAVY) {
  return singleColTable([
    p([r(label, { bold:true, size:22, color:textColor })]),
  ], fill, allNone, { top:100, bottom:100, left:240, right:240 });
}

function talkingPointBox(lines) {
  return singleColTable([
    p([r("WHAT TO SAY  —  Sample Opening Script", { bold:true, size:18, color:STEEL })]),
    spacer(60),
    ...lines.map(line => p([r(line, { size:19, color:DARK, italics: line.startsWith('"') })])
    ),
  ], LT_BLUE, { top:sb(STEEL,4), bottom:sb("AAAAAA"), left:sb(STEEL,4), right:sb("AAAAAA") }, { top:140,bottom:140,left:240,right:240 });
}

function objectionBox(pairs) {
  const rows = [
    new TableRow({ children: [
      new TableCell({ shading:{fill:NAVY,type:ShadingType.CLEAR}, borders:allNone, margins:{top:80,bottom:80,left:160,right:160}, width:{size:4200,type:WidthType.DXA},
        children:[p([r("THEY SAY", {bold:true,size:18,color:WHITE})])] }),
      new TableCell({ shading:{fill:NAVY,type:ShadingType.CLEAR}, borders:allNone, margins:{top:80,bottom:80,left:160,right:160}, width:{size:5160,type:WidthType.DXA},
        children:[p([r("TJ SAYS", {bold:true,size:18,color:WHITE})])] }),
    ]}),
    ...pairs.map(([obj,resp],i) => new TableRow({ children: [
      new TableCell({ shading:{fill:i%2===0?LT_GRAY:WHITE,type:ShadingType.CLEAR}, borders:topBottom(), margins:{top:100,bottom:100,left:160,right:160}, width:{size:4200,type:WidthType.DXA},
        children:[p([r(obj,{size:19,color:DARK,italics:true})])] }),
      new TableCell({ shading:{fill:i%2===0?LT_GRAY:WHITE,type:ShadingType.CLEAR}, borders:topBottom(), margins:{top:100,bottom:100,left:160,right:160}, width:{size:5160,type:WidthType.DXA},
        children:[p([r(resp,{size:19,color:DARK})])] }),
    ]}))
  ];
  return new Table({ width:{size:9360,type:WidthType.DXA}, columnWidths:[4200,5160], rows });
}

function marketingBox(tactics) {
  return singleColTable([
    p([r("LOW-COST MARKETING TACTICS FOR INDUSTRIAL BUYERS", { bold:true, size:18, color:GREEN })]),
    p([r("These buyers don't scroll Instagram. They read trade journals, attend shows, and trust referrals. Here's how to reach them.", { size:19, color:DARK, italics:true })], { spacing:{before:60,after:120} }),
    ...tactics.map(([tactic, detail]) => new Table({
      width:{size:8800,type:WidthType.DXA},
      columnWidths:[2200,6600],
      rows:[new TableRow({ children:[
        new TableCell({ shading:{fill:GREEN,type:ShadingType.CLEAR}, borders:allNone, margins:{top:80,bottom:80,left:140,right:140}, width:{size:2200,type:WidthType.DXA},
          children:[p([r(tactic,{bold:true,size:19,color:WHITE})])] }),
        new TableCell({ shading:{fill:LT_GRN,type:ShadingType.CLEAR}, borders:allNone, margins:{top:80,bottom:80,left:140,right:140}, width:{size:6600,type:WidthType.DXA},
          children:[p([r(detail,{size:19,color:DARK})])] }),
      ]})]
    })),
  ], LT_GRN, { top:sb(GREEN,4), bottom:sb("AAAAAA"), left:sb(GREEN,4), right:sb("AAAAAA") }, { top:160,bottom:160,left:240,right:240 });
}

function costBadge(cost, timeToFirstSale) {
  return new Table({
    width:{size:9360,type:WidthType.DXA},
    columnWidths:[4680,4680],
    rows:[new TableRow({ children:[
      new TableCell({ shading:{fill:LT_GOLD,type:ShadingType.CLEAR}, borders:{top:sb(GOLD,3),bottom:sb(GOLD,3),left:sb(GOLD,3),right:sb("DDDDDD")}, margins:{top:120,bottom:120,left:200,right:200}, width:{size:4680,type:WidthType.DXA},
        children:[
          p([r("ESTIMATED MARKETING COST",{bold:true,size:17,color:GOLD})]),
          p([r(cost,{bold:true,size:24,color:DARK})],{spacing:{before:60}}),
        ] }),
      new TableCell({ shading:{fill:LT_GOLD,type:ShadingType.CLEAR}, borders:{top:sb(GOLD,3),bottom:sb(GOLD,3),left:sb("DDDDDD"),right:sb(GOLD,3)}, margins:{top:120,bottom:120,left:200,right:200}, width:{size:4680,type:WidthType.DXA},
        children:[
          p([r("REALISTIC TIME TO FIRST SALE",{bold:true,size:17,color:GOLD})]),
          p([r(timeToFirstSale,{bold:true,size:24,color:DARK})],{spacing:{before:60}}),
        ] }),
    ]})]
  });
}

// ════════════════════════════════════════════════════════════════════════════
// IDEA SECTIONS
// ════════════════════════════════════════════════════════════════════════════

function idea01() {
  return [
    pageBreak(),
    spacer(60),
    ideaHeader("01","AI-Powered CNC Machine Valuation Service","The 'Kelley Blue Book' for used industrial machinery"),
    spacer(100),

    sectionLabel("WHO TO CALL  —  The Right Person in the Room"),
    spacer(60),
    p([r("For banks, lenders, and PE firms:", {bold:true,size:20,color:NAVY})]),
    bullet("Commercial Loan Officers at regional banks (ask for equipment lending desk)"),
    bullet("Asset-Based Lending (ABL) teams at mid-size banks — they order valuations constantly"),
    bullet("Senior Associates or VPs at private equity firms with manufacturing portfolio companies"),
    bullet("Turnaround consultants and restructuring advisors — they need valuations fast when deals are in distress"),
    spacer(80),
    p([r("For manufacturers and plant managers:", {bold:true,size:20,color:NAVY})]),
    bullet("Plant Manager or Facilities Director — owns the equipment, knows what's on the floor"),
    bullet("CFO or Controller at mid-size manufacturers — they handle insurance, depreciation, and asset sales"),
    bullet("Operations VP when a facility is being restructured or consolidated"),
    bullet("Estate and probate attorneys when a business owner passes and assets must be valued"),
    spacer(100),

    sectionLabel("HOW TO GET IN THE ROOM  —  Step-by-Step Approach"),
    spacer(60),
    p([r("Step 1: Build your short list of 20 targets", {bold:true,size:20,color:STEEL})]),
    bullet("Search LinkedIn for 'commercial loan officer' + 'equipment financing' + Tennessee (or neighboring states)"),
    bullet("Search for manufacturing companies within 150 miles of Smyrna with 50–500 employees on LinkedIn or Dun & Bradstreet"),
    bullet("Call your existing Opincar client list — ask who handles their equipment valuations today"),
    spacer(80),
    p([r("Step 2: Send a physical letter or one-page flyer — not an email", {bold:true,size:20,color:STEEL})]),
    bullet("Industrial buyers open physical mail. Email gets buried. A one-page letter on Opincar letterhead to a bank's ABL desk will get read."),
    bullet("Address it to the department or role, not just the company. 'Attention: Equipment Lending Team' works fine."),
    spacer(80),
    p([r("Step 3: Follow up by phone 5–7 days later", {bold:true,size:20,color:STEEL})]),
    bullet("Call the main number, ask for the commercial lending or equipment finance department"),
    bullet("Keep it short: 'I sent a letter last week about our machine valuation service — just wanted to make sure it landed with the right person'"),
    spacer(80),
    p([r("Step 4: Offer a free sample valuation on one machine", {bold:true,size:20,color:STEEL})]),
    bullet("For the first 3–5 prospects, offer to run a complimentary valuation on one machine they already own"),
    bullet("Let the quality of the report close the deal — industrial buyers trust proof, not pitches"),
    spacer(80),
    p([r("Step 5: Ask for the referral network", {bold:true,size:20,color:STEEL})]),
    bullet("Once you have a happy client, ask directly: 'Who else in your firm, or other banks/firms you work with, might need this?'"),
    bullet("ABL lending is a small world — one relationship opens the door to five more"),
    spacer(100),

    talkingPointBox([
      r("Opening line when calling a bank:", {bold:true,size:19,color:STEEL}),
      r(""),
      r('"Hi, my name is TJ Opincar with Opincar Machinery in Smyrna. We\'ve been dealing heavy industrial CNC equipment for years and we just launched a formal machine valuation service for banks and lenders. When your team needs a fair market value on a borrower\'s manufacturing equipment, we can turn that around faster and more accurately than most appraisers because we\'re active in the market every single day. Do you have five minutes or would a one-page overview be more helpful first?"', {size:19,color:DARK,italics:true}),
    ]),
    spacer(100),

    sectionLabel("HANDLING OBJECTIONS"),
    spacer(60),
    objectionBox([
