      ["Pre-Auction\nDirect Outreach", "Two to three weeks before any major IronPlanet or Ritchie Bros. auction, pull the catalog and identify the plant managers and procurement contacts most likely to care about those machines. Call or email them directly. This is the highest-ROI marketing channel — you're reaching out at the exact moment the need is live."],
      ["IronPlanet & Ritchie\nBros. Seller Network", "Both platforms have seller communities and dealer networks. TJ is already in this world as a buyer and sometimes seller. Making it known — in conversations, in email signatures, in dealer profile bios — that he offers advisory services costs nothing."],
      ["Auction Platform\nSponsored Email", "IronPlanet and Hilco both offer sponsored email and advertising to their buyer databases. A single sponsored email blast to buyers in a specific equipment category can cost $500–$2,000 but reaches a hyper-targeted industrial audience."],
      ["Newsletter to\nExisting Clients", "Start a simple monthly or bi-weekly email newsletter — 'Opincar Market Intelligence' — and send it to every past Opincar buyer. Include upcoming auctions, notable lots, and market commentary. Subscribers who find it valuable will pay for more. Cost: zero to $50/month (email platform)."],
      ["LinkedIn Articles", "Post a short LinkedIn article after each major auction: 'What I Saw at the Ritchie Bros. Auction Last Week — What Sold, What Was a Deal, and What Was a Trap.' Industrial buyers read this content and it positions TJ as the market expert. Over time this builds an inbound audience. Cost: zero."],
    ]),
    spacer(100),
    costBadge("$100–$400/month to start", "First advisory client in 30–45 days with targeted pre-auction outreach"),
  ];
}

// ── CLOSING PAGE ──────────────────────────────────────────────────────────────
function closingPage() {
  return [
    pageBreak(),
    spacer(200),
    singleColTable([
      p([r("THE UNIVERSAL RULE FOR SELLING TO INDUSTRIAL BUYERS", {bold:true,size:26,color:WHITE})], {alignment:AlignmentType.CENTER}),
    ], NAVY, allNone, {top:180,bottom:120,left:300,right:300}),
    singleColTable([
      p([r("These buyers don't want to be marketed to. They want to be helped.", {bold:true,size:22,color:NAVY})], {alignment:AlignmentType.CENTER}),
      spacer(80),
      p([r("Every tactic in this playbook follows the same principle: lead with value, demonstrate expertise, and let the quality of TJ's knowledge do the selling. Industrial buyers are skeptical of vendors, but deeply loyal to partners who make their jobs easier.", {size:20,color:DARK})], {spacing:{before:60,after:60}}),
      p([r("The buyers in this space are not on Instagram and they don't click banner ads. They take phone calls from people they know or people who were referred to them. They read trade publications at their desk. They attend the same industry events year after year. They trust proof over promises.", {size:20,color:DARK})], {spacing:{before:60,after:100}}),
      new Table({
        width:{size:8800,type:WidthType.DXA},
        columnWidths:[4400,4400],
        rows:[new TableRow({ children:[
          new TableCell({ shading:{fill:LT_BLUE,type:ShadingType.CLEAR}, borders:allGray, margins:{top:120,bottom:120,left:200,right:200}, width:{size:4400,type:WidthType.DXA},
            children:[
              p([r("What Works:", {bold:true,size:20,color:NAVY})]),
              ...[
                "Personal phone calls",
                "Physical mail to the right title",
                "Referrals from attorneys, bankers, brokers",
                "Trade publications and directories",
                "Google search (for people actively looking)",
                "LinkedIn (targeted, personal outreach only)",
                "Industry associations and shows",
                "Proof: case studies, sample reports, demos"
              ].map(t => bullet(t, GREEN, false))
            ]
          }),
          new TableCell({ shading:{fill:"FEF0F0",type:ShadingType.CLEAR}, borders:allGray, margins:{top:120,bottom:120,left:200,right:200}, width:{size:4400,type:WidthType.DXA},
            children:[
              p([r("What Doesn't:", {bold:true,size:20,color:RED})]),
              ...[
                "Instagram, TikTok, Facebook",
                "Mass email blasts to cold lists",
                "Generic Google display ads",
                "Vague branding campaigns",
                "Waiting for inbound leads only",
                "Complex sales funnels or webinars",
                "Expensive sponsorships without follow-up",
                "Selling before establishing credibility"
              ].map(t => bullet(t, RED, false))
            ]
          })
        ]})]
      }),
    ], LT_GRAY, allNone, {top:180,bottom:180,left:240,right:240}),
    spacer(200),
    singleColTable([
      p([r("Prepared exclusively for TJ Opincar  ·  Opincar Machinery, Smyrna TN  ·  February 2026", {size:18,color:"AAAAAA"})], {alignment:AlignmentType.CENTER}),
    ], DARK, allNone, {top:160,bottom:160,left:300,right:300}),
  ];
}

// ════════════════════════════════════════════════════════════════════════════
const doc = new Document({
  numbering: {
    config: [
      { reference:"bullets", levels:[{ level:0, format:LevelFormat.BULLET, text:"•", alignment:AlignmentType.LEFT, style:{paragraph:{indent:{left:720,hanging:360}}} }] },
      { reference:"bullets2", levels:[{ level:0, format:LevelFormat.BULLET, text:"◦", alignment:AlignmentType.LEFT, style:{paragraph:{indent:{left:1080,hanging:360}}} }] },
      { reference:"numbers", levels:[{ level:0, format:LevelFormat.DECIMAL, text:"%1.", alignment:AlignmentType.LEFT, style:{paragraph:{indent:{left:720,hanging:360}}} }] },
    ]
  },
  styles: {
    default: { document: { run: { font:"Arial", size:20, color:DARK } } },
    paragraphStyles: [
      { id:"Heading1", name:"Heading 1", basedOn:"Normal", next:"Normal", quickFormat:true, run:{size:34,bold:true,font:"Arial"}, paragraph:{spacing:{before:240,after:120},outlineLevel:0} },
      { id:"Heading2", name:"Heading 2", basedOn:"Normal", next:"Normal", quickFormat:true, run:{size:26,bold:true,font:"Arial"}, paragraph:{spacing:{before:180,after:100},outlineLevel:1} },
    ]
  },
  sections: [{
    properties: {
      page: { size:{width:12240,height:15840}, margin:{top:1440,right:1440,bottom:1440,left:1440} }
    },
    children: [
      ...coverPage(),
      ...idea01(),
      ...idea02(),
      ...idea03(),
      ...idea04(),
      ...idea05(),
      ...idea06(),
      ...closingPage(),
    ]
  }]
});

Packer.toBuffer(doc).then(buf => {
  fs.writeFileSync('/home/claude/opincar_sales_playbook.docx', buf);
  console.log('Done!');
});

