const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, BorderStyle, WidthType, ShadingType, LevelFormat,
  HeadingLevel
} = require('docx');
const fs = require('fs');

const NAVY   = "1C2B4A";
const STEEL  = "2E6DA4";
const GOLD   = "C9922A";
const GREEN  = "1A5C36";
const LT_BLUE= "D9E8F5";
const LT_GRN = "D5EEE0";
const LT_GOLD= "FAF0DC";
const LT_GRAY= "F2F4F6";
const WHITE  = "FFFFFF";
const DARK   = "1E2A35";

const nb = () => ({ style: BorderStyle.NONE, size: 0, color: WHITE });
const sb = (c="CCCCCC", sz=1) => ({ style: BorderStyle.SINGLE, size: sz, color: c });
const allNone = { top: nb(), bottom: nb(), left: nb(), right: nb() };
const allGray = { top: sb(), bottom: sb(), left: sb(), right: sb() };
const topBottomOnly = (c="CCCCCC") => ({ top: sb(c), bottom: sb(c), left: nb(), right: nb() });

function r(text, opts={}) { return new TextRun({ text, font: "Arial", ...opts }); }
function p(children, opts={}) {
  return new Paragraph({ children: Array.isArray(children) ? children : [r(children, {size:20,color:DARK})], ...opts });
}
function spacer(sz=120) { return new Paragraph({ spacing:{before:sz,after:sz}, children:[r("")] }); }

function singleCell(children, fill, borders, margins={top:160,bottom:160,left:240,right:240}) {
  return new Table({
    width:{size:9360,type:WidthType.DXA}, columnWidths:[9360],
    rows:[new TableRow({ children:[new TableCell({
      shading:{fill,type:ShadingType.CLEAR}, borders, margins,
      width:{size:9360,type:WidthType.DXA},
      children: Array.isArray(children) ? children : [children]
    })] })]
  });
}

function bullet(text, color=DARK, bold=false) {
  return new Paragraph({
    numbering:{reference:"bullets",level:0},
    spacing:{before:50,after:50},
    children:[r(text,{size:20,color,bold})]
  });
}

// ── HEADER BAND ──────────────────────────────────────────────────────────────
const headerBand = singleCell([
  p([r("OPINCAR MACHINERY", {bold:true,size:20,color:"7FA8C9"})], {spacing:{before:0,after:60}}),
  p([r("CLIENT CASE STUDY", {bold:true,size:36,color:WHITE})]),
  p([r("AI-Powered CNC Machine Valuation Service", {size:24,color:"AAC8E8",italics:true})], {spacing:{before:80,after:60}}),
  p([r("How a Regional Lender Reduced Appraisal Turnaround from 3 Weeks to 48 Hours", {size:20,color:"7FA8C9"})]),
], NAVY, allNone, {top:240,bottom:240,left:320,right:320});

// ── SNAPSHOT ROW ─────────────────────────────────────────────────────────────
function snapCell(label, value, fill) {
  return new TableCell({
    shading:{fill,type:ShadingType.CLEAR}, borders:allNone,
    margins:{top:140,bottom:140,left:180,right:180},
    width:{size:2340,type:WidthType.DXA},
    children:[
      p([r(label,{bold:true,size:17,color:STEEL})], {alignment:AlignmentType.CENTER}),
      p([r(value,{bold:true,size:26,color:NAVY})], {alignment:AlignmentType.CENTER,spacing:{before:40}}),
    ]
  });
}
const snapshotRow = new Table({
  width:{size:9360,type:WidthType.DXA}, columnWidths:[2340,2340,2340,2340],
  rows:[new TableRow({ children:[
    snapCell("CLIENT TYPE","Regional Lender",LT_BLUE),
    snapCell("MACHINES VALUED","14 CNC Units",LT_BLUE),
    snapCell("TURNAROUND","48 Hours",LT_GRN),
    snapCell("OUTCOME","Loan Approved",LT_GOLD),
  ]})]
});

// ── TJ BIO SIDEBAR ────────────────────────────────────────────────────────────
const tjBio = new Table({
  width:{size:9360,type:WidthType.DXA}, columnWidths:[6200,3160],
  rows:[new TableRow({ children:[
    // Left: situation
    new TableCell({
      shading:{fill:WHITE,type:ShadingType.CLEAR},
      borders:{top:nb(),bottom:nb(),left:nb(),right:sb("DDDDDD")},
      margins:{top:0,bottom:0,left:0,right:240},
      width:{size:6200,type:WidthType.DXA},
      children:[
        p([r("THE SITUATION",{bold:true,size:17,color:STEEL})]),
        p([r("A regional bank in Middle Tennessee had an existing commercial borrower — a precision machining company — applying for a $1.2 million equipment line of credit. The borrower's collateral consisted of 14 CNC machines on the shop floor, ranging from a 2008 Mazak horizontal machining center to a 2015 Doosan CNC lathe.", {size:19,color:DARK})],{spacing:{before:60,after:100}}),
        p([r("The bank's standard third-party appraiser had a 3-week backlog. The loan was time-sensitive — the borrower needed the capital to fulfill a new contract — and the lending officer needed a reliable fair market value quickly. A colleague referred them to Opincar Machinery.", {size:19,color:DARK})],{spacing:{before:0,after:0}}),
      ]
    }),
    // Right: TJ bio
    new TableCell({
      shading:{fill:LT_BLUE,type:ShadingType.CLEAR},
      borders:{top:nb(),bottom:nb(),left:nb(),right:nb()},
      margins:{top:0,bottom:0,left:240,right:0},
      width:{size:3160,type:WidthType.DXA},
      children:[
        p([r("ABOUT TJ OPINCAR",{bold:true,size:17,color:NAVY})]),
        spacer(60),
        p([r("25+ Years",{bold:true,size:28,color:STEEL})],{spacing:{before:0,after:40}}),
        p([r("in Heavy Industrial CNC Machinery",{size:18,color:DARK})]),
        spacer(80),
        p([r("TJ Opincar has been buying, selling, appraising, and rigging heavy CNC machinery since the late 1990s. His hands-on experience spans boring mills, machining centers, lathes, grinders, press brakes, and plate fabrication equipment across dozens of industries.", {size:18,color:DARK})],{spacing:{before:0,after:80}}),
        p([r("He has personally handled hundreds of machine transactions, plant closures, and equipment appraisals — giving him market pricing knowledge that no desk-based appraiser can replicate.", {size:18,color:DARK})]),
      ]
    }),
  ]})]
});

// ── WHAT WE DID ──────────────────────────────────────────────────────────────
const whatWeDid = [
  singleCell([
    p([r("WHAT OPINCAR DID",{bold:true,size:22,color:WHITE})]),
  ], NAVY, allNone, {top:120,bottom:120,left:240,right:240}),
  spacer(80),
  new Table({
    width:{size:9360,type:WidthType.DXA}, columnWidths:[440,8920],
    rows:[
      ...[
        ["01", "Received the machine list and specs from the borrower — make, model, year of manufacture, approximate hours, and any known maintenance history."],
        ["02", "TJ personally reviewed each machine against his 25+ years of active market knowledge, cross-referencing current dealer listings, recent auction results, and private sale comparables."],
        ["03", "Our AI-assisted valuation system pulled OEM specification data, depreciation curves, and current market comparables for each machine model, generating a draft valuation range for TJ's review."],
        ["04", "TJ adjusted each machine's value based on condition notes, the borrower's specific maintenance practices, and his knowledge of current regional demand for each machine type."],
        ["05", "A formal 14-machine Valuation Report was produced within 48 hours of receiving the request — complete with individual machine assessments, market comparable data, condition commentary, and a total fair market value range for the collateral package."],
        ["06", "TJ remained available to the lending officer for follow-up questions and to explain any specific valuation conclusion the bank's underwriting team needed clarified."],
      ].map(([num, text], i) => new TableRow({ children:[
        new TableCell({
          shading:{fill:i%2===0?LT_BLUE:WHITE,type:ShadingType.CLEAR},
          borders:topBottomOnly(),
          margins:{top:100,bottom:100,left:120,right:120},
          width:{size:440,type:WidthType.DXA},
          children:[p([r(num,{bold:true,size:22,color:STEEL})],{alignment:AlignmentType.CENTER})]
        }),
        new TableCell({
          shading:{fill:i%2===0?LT_BLUE:WHITE,type:ShadingType.CLEAR},
          borders:topBottomOnly(),
          margins:{top:100,bottom:100,left:180,right:120},
          width:{size:8920,type:WidthType.DXA},
          children:[p([r(text,{size:19,color:DARK})])]
        }),
      ]}))
    ]
  }),
];

// ── RESULTS ──────────────────────────────────────────────────────────────────
const results = [
  spacer(80),
  singleCell([
    p([r("THE RESULTS",{bold:true,size:22,color:WHITE})]),
  ], GREEN, allNone, {top:120,bottom:120,left:240,right:240}),
  spacer(80),
  new Table({
    width:{size:9360,type:WidthType.DXA}, columnWidths:[3120,3120,3120],
    rows:[new TableRow({ children:[
      new TableCell({
        shading:{fill:LT_GRN,type:ShadingType.CLEAR},
        borders:{top:sb(GREEN,4),bottom:sb(),left:sb(GREEN,4),right:sb()},
        margins:{top:140,bottom:140,left:180,right:180},
        width:{size:3120,type:WidthType.DXA},
        children:[
          p([r("Turnaround Time",{bold:true,size:18,color:GREEN})]),
          p([r("3 weeks",{size:18,color:"888888"})],{spacing:{before:40}}),
          p([r("Reduced to 48 Hours",{bold:true,size:20,color:DARK})],{spacing:{before:20}}),
        ]
      }),
      new TableCell({
        shading:{fill:LT_GRN,type:ShadingType.CLEAR},
        borders:{top:sb(GREEN,4),bottom:sb(),left:nb(),right:sb()},
        margins:{top:140,bottom:140,left:180,right:180},
        width:{size:3120,type:WidthType.DXA},
        children:[
          p([r("Collateral Clarity",{bold:true,size:18,color:GREEN})]),
          p([r("Unknown / estimated",{size:18,color:"888888"})],{spacing:{before:40}}),
          p([r("14-machine individual assessments delivered",{bold:true,size:20,color:DARK})],{spacing:{before:20}}),
        ]
      }),
      new TableCell({
        shading:{fill:LT_GRN,type:ShadingType.CLEAR},
        borders:{top:sb(GREEN,4),bottom:sb(),left:nb(),right:sb(GREEN,4)},
        margins:{top:140,bottom:140,left:180,right:180},
        width:{size:3120,type:WidthType.DXA},
        children:[
          p([r("Loan Decision",{bold:true,size:18,color:GREEN})]),
          p([r("Stalled pending appraisal",{size:18,color:"888888"})],{spacing:{before:40}}),
          p([r("Approved within 72 hours of report delivery",{bold:true,size:20,color:DARK})],{spacing:{before:20}}),
        ]
      }),
    ]})]
  }),
];

// ── QUOTE BLOCK ───────────────────────────────────────────────────────────────
const quoteBlock = singleCell([
  p([r("\u201CWe needed an accurate machine value fast and our normal appraiser couldn\u2019t get to it for three weeks. TJ turned around a full 14-machine report in under 48 hours, and the detail level was better than what we typically get from a formal USPAP appraisal. Our underwriting team had exactly what they needed to approve the credit facility. We\u2019ll be using Opincar for every equipment-collateral deal going forward.\u201D",
    {size:21,color:DARK,italics:true})]),
  spacer(80),
  p([r("— Senior Commercial Lending Officer, Regional Bank, Middle Tennessee",{bold:true,size:19,color:STEEL})]),
], LT_GOLD, {top:sb(GOLD,4),bottom:sb(GOLD,4),left:sb(GOLD,4),right:sb(GOLD,4)}, {top:200,bottom:200,left:280,right:280});

// ── WHY TJ ────────────────────────────────────────────────────────────────────
const whyTJ = [
  spacer(80),
  singleCell([
    p([r("WHY TJ OPINCAR — NOT JUST ANY APPRAISER",{bold:true,size:22,color:WHITE})]),
  ], NAVY, allNone, {top:120,bottom:120,left:240,right:240}),
  spacer(80),
  p([r("Most appraisers are generalists who rely on published price guides and comparable sales data. TJ Opincar is an active market participant who has personally bought and sold this exact equipment — in this exact market — for over 25 years. That difference matters when the stakes are a million-dollar credit facility.",{size:20,color:DARK})]),
  spacer(60),
  new Table({
    width:{size:9360,type:WidthType.DXA}, columnWidths:[4680,4680],
    rows:[new TableRow({ children:[
      new TableCell({
        shading:{fill:LT_BLUE,type:ShadingType.CLEAR},
        borders:allGray,
        margins:{top:140,bottom:140,left:180,right:180},
        width:{size:4680,type:WidthType.DXA},
        children:[
          p([r("What a Typical Appraiser Brings",{bold:true,size:19,color:"666666"})]),
          spacer(40),
          ...[
            "Price guide and database lookups",
            "USPAP compliance framework",
            "2–4 week turnaround typical",
            "General industrial equipment knowledge",
            "No active market participation",
          ].map(t => bullet(t,"666666"))
        ]
      }),
      new TableCell({
        shading:{fill:LT_BLUE,type:ShadingType.CLEAR},
        borders:allGray,
        margins:{top:140,bottom:140,left:180,right:180},
        width:{size:4680,type:WidthType.DXA},
        children:[
          p([r("What TJ Opincar Brings",{bold:true,size:19,color:NAVY})]),
          spacer(40),
          ...[
            "25+ years of active buying and selling CNC machinery",
            "Real-time knowledge of current market pricing",
            "48-hour turnaround on most engagements",
            "Deep specialty expertise: boring mills, lathes, machining centers, grinders, press brakes",
            "Direct access to auction results and private dealer network",
          ].map(t => bullet(t,GREEN,true))
        ]
      }),
    ]})]
  }),
];

// ── FOOTER ────────────────────────────────────────────────────────────────────
const footer = [
  spacer(120),
  singleCell([
    p([r("READY TO PUT 25 YEARS OF MARKET KNOWLEDGE TO WORK FOR YOUR NEXT DEAL?",{bold:true,size:20,color:WHITE})],{alignment:AlignmentType.CENTER}),
    spacer(60),
    p([r("TJ Opincar  ·  Opincar Machinery  ·  7857 S Lamar Rd, Smyrna, TN 37167",{size:19,color:"AAC8E8"})],{alignment:AlignmentType.CENTER}),
    p([r("(615) 459-7983  ·  tom@opincarmachinery.com  ·  opincarmachinery.com",{size:19,color:"AAC8E8"})],{alignment:AlignmentType.CENTER,spacing:{before:40}}),
  ], NAVY, allNone, {top:200,bottom:200,left:300,right:300}),
