const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, BorderStyle, WidthType, ShadingType, LevelFormat,
} = require('docx');
const fs = require('fs');

const NAVY   = "1C2B4A";
const STEEL  = "2E6DA4";
const GOLD   = "C9922A";
const GREEN  = "1A5C36";
const RED    = "8B1A1A";
const LT_BLUE= "D9E8F5";
const LT_GRN = "D5EEE0";
const LT_GOLD= "FAF0DC";
const LT_RED = "FAEAEA";
const LT_GRAY= "F2F4F6";
const WHITE  = "FFFFFF";
const DARK   = "1E2A35";

const nb = () => ({ style: BorderStyle.NONE, size: 0, color: WHITE });
const sb = (c="CCCCCC",sz=1) => ({ style: BorderStyle.SINGLE, size: sz, color: c });
const allNone = { top:nb(),bottom:nb(),left:nb(),right:nb() };
const allGray  = { top:sb(),bottom:sb(),left:sb(),right:sb() };
const topBot = (c="CCCCCC") => ({ top:sb(c),bottom:sb(c),left:nb(),right:nb() });

function r(text,opts={}) { return new TextRun({text,font:"Arial",...opts}); }
function p(children,opts={}) {
  return new Paragraph({children:Array.isArray(children)?children:[r(children,{size:20,color:DARK})],...opts});
}
function spacer(sz=120) { return new Paragraph({spacing:{before:sz,after:sz},children:[r("")]}); }
function bullet(text,color=DARK,bold=false) {
  return new Paragraph({numbering:{reference:"bullets",level:0},spacing:{before:50,after:50},children:[r(text,{size:20,color,bold})]});
}
function singleCell(children,fill,borders,margins={top:160,bottom:160,left:240,right:240}) {
  return new Table({
    width:{size:9360,type:WidthType.DXA},columnWidths:[9360],
    rows:[new TableRow({children:[new TableCell({
      shading:{fill,type:ShadingType.CLEAR},borders,margins,
      width:{size:9360,type:WidthType.DXA},
      children:Array.isArray(children)?children:[children]
    })]})]
  });
}

// ── HEADER ────────────────────────────────────────────────────────────────────
const headerBand = singleCell([
  p([r("OPINCAR MACHINERY",{bold:true,size:20,color:"7FA8C9"})],{spacing:{before:0,after:60}}),
  p([r("CLIENT CASE STUDY",{bold:true,size:36,color:WHITE})]),
  p([r("Condition Intelligence Reports",{size:24,color:"AAC8E8",italics:true})],{spacing:{before:80,after:60}}),
  p([r("How a Contract Manufacturer Avoided a $28,000 Refurbishment Surprise on a Used Machining Center",{size:20,color:"7FA8C9"})]),
],NAVY,allNone,{top:240,bottom:240,left:320,right:320});

// ── SNAPSHOT ──────────────────────────────────────────────────────────────────
function snapCell(label,value,sub,fill) {
  return new TableCell({
    shading:{fill,type:ShadingType.CLEAR},borders:allNone,
    margins:{top:140,bottom:140,left:160,right:160},
    width:{size:2340,type:WidthType.DXA},
    children:[
      p([r(label,{bold:true,size:17,color:STEEL})],{alignment:AlignmentType.CENTER}),
      p([r(value,{bold:true,size:26,color:NAVY})],{alignment:AlignmentType.CENTER,spacing:{before:40}}),
      p([r(sub,{size:17,color:"555555",italics:true})],{alignment:AlignmentType.CENTER,spacing:{before:20}}),
    ]
  });
}
const snapshotRow = new Table({
  width:{size:9360,type:WidthType.DXA},columnWidths:[2340,2340,2340,2340],
  rows:[new TableRow({children:[
    snapCell("CLIENT TYPE","Contract Mfr.","Aerospace components",LT_BLUE),
    snapCell("MACHINE","HMC 630","2014 Doosan","LT_BLUE"),
    snapCell("SURPRISE FOUND","$28,400","in hidden issues",LT_RED),
    snapCell("OUTCOME","Renegotiated","Price reduced $22K",LT_GRN),
  ]})]
});

// ── SITUATION / TJ BIO ───────────────────────────────────────────────────────
const situationBio = new Table({
  width:{size:9360,type:WidthType.DXA},columnWidths:[6000,3360],
  rows:[new TableRow({children:[
    new TableCell({
      shading:{fill:WHITE,type:ShadingType.CLEAR},
      borders:{top:nb(),bottom:nb(),left:nb(),right:sb("DDDDDD")},
      margins:{top:0,bottom:0,left:0,right:240},
      width:{size:6000,type:WidthType.DXA},
      children:[
        p([r("THE SITUATION",{bold:true,size:17,color:STEEL})]),
        p([r("A contract manufacturer in the Nashville area had located a 2014 Doosan HMC 630 Horizontal Machining Center at a dealer in Ohio. The asking price was $185,000. The photos looked clean, the seller claimed the machine had 'low hours and was well maintained,' and the buyer was ready to move forward.",{size:19,color:DARK})],{spacing:{before:60,after:100}}),
        p([r("Before wiring the funds, the company's operations director reached out to TJ Opincar — someone he had done business with years earlier — and asked if TJ would take a look at the listing and the photos before the deal closed.",{size:19,color:DARK})],{spacing:{before:0,after:100}}),
        p([r("What came back was not what the buyer expected.",{size:19,color:DARK,bold:true})]),
      ]
    }),
    new TableCell({
      shading:{fill:LT_BLUE,type:ShadingType.CLEAR},
      borders:{top:nb(),bottom:nb(),left:nb(),right:nb()},
      margins:{top:0,bottom:0,left:240,right:0},
      width:{size:3360,type:WidthType.DXA},
      children:[
        p([r("ABOUT TJ OPINCAR",{bold:true,size:17,color:NAVY})]),
