        p([r("25+ Years",{bold:true,size:28,color:STEEL})],{spacing:{before:0,after:40}}),
        p([r("in Heavy Industrial CNC Machinery",{size:18,color:DARK})]),
        spacer(80),
        p([r("TJ has personally inspected, bought, sold, and moved hundreds of horizontal machining centers, CNC lathes, and boring mills across his career. He knows these machines the way a mechanic knows engines — by the wear patterns, the maintenance tells, and the things sellers don't mention in the listing.",{size:18,color:DARK})],{spacing:{before:0,after:80}}),
        p([r("When TJ reviews a machine, he's not reading a checklist. He's applying decades of pattern recognition that no software alone can replicate.",{size:18,color:DARK,italics:true})]),
      ]
    }),
  ]})]
});

// ── WHAT WE FOUND ─────────────────────────────────────────────────────────────
const whatWeFound = [
  spacer(80),
  singleCell([p([r("WHAT OPINCAR FOUND",{bold:true,size:22,color:WHITE})])],NAVY,allNone,{top:120,bottom:120,left:240,right:240}),
  spacer(80),
  p([r("TJ reviewed the available photos, the machine specs, the seller's maintenance claims, and applied his market knowledge to produce an Opincar Condition Intelligence Report. Here is a summary of what the report flagged:",{size:20,color:DARK})]),
  spacer(80),
  new Table({
    width:{size:9360,type:WidthType.DXA},columnWidths:[1440,5280,2640],
    rows:[
      new TableRow({children:[
        new TableCell({shading:{fill:NAVY,type:ShadingType.CLEAR},borders:allNone,margins:{top:80,bottom:80,left:140,right:140},width:{size:1440,type:WidthType.DXA},children:[p([r("FINDING",{bold:true,size:18,color:WHITE})])]}),
        new TableCell({shading:{fill:NAVY,type:ShadingType.CLEAR},borders:allNone,margins:{top:80,bottom:80,left:140,right:140},width:{size:5280,type:WidthType.DXA},children:[p([r("DETAIL",{bold:true,size:18,color:WHITE})])]}),
        new TableCell({shading:{fill:NAVY,type:ShadingType.CLEAR},borders:allNone,margins:{top:80,bottom:80,left:140,right:140},width:{size:2640,type:WidthType.DXA},children:[p([r("EST. COST TO REMEDY",{bold:true,size:18,color:WHITE})])]}),
      ]}),
      ...[
        ["Spindle Wear","Photo angles avoided direct spindle face shots — a common tell when sellers know there is wear. Based on the machine's stated hours and vintage, TJ flagged likely spindle bearing wear requiring inspection and probable rebuild.","$8,000 – $12,000"],
        ["Way Cover Condition","Visible oil staining pattern on the machine base in background of one photo indicates likely way cover seal degradation. Unchecked, this leads to accelerated way wear.","$2,200 – $3,500"],
        ["Control System","The control listed (Fanuc 18i) is end-of-life with discontinued support. Replacement parts are scarce and expensive. A modern control retrofit would be needed within 2–4 years.","$9,500 – $14,000"],
        ["Tool Changer","Machine age and hours-per-shift estimate suggests tool changer arms and cam mechanism are approaching service interval. Seller made no mention of recent service.","$3,200 – $4,800"],
        ["Coolant System","Coolant tank in one photo shows visible residue buildup consistent with extended intervals between coolant changes — potential pump and line contamination.","$800 – $1,200"],
      ].map(([finding,detail,cost],i) => new TableRow({children:[
        new TableCell({shading:{fill:i%2===0?LT_RED:"FEFEFE",type:ShadingType.CLEAR},borders:topBot(),margins:{top:100,bottom:100,left:140,right:140},width:{size:1440,type:WidthType.DXA},children:[p([r(finding,{size:18,color:RED,bold:true})])]}),
        new TableCell({shading:{fill:i%2===0?LT_RED:"FEFEFE",type:ShadingType.CLEAR},borders:topBot(),margins:{top:100,bottom:100,left:140,right:140},width:{size:5280,type:WidthType.DXA},children:[p([r(detail,{size:18,color:DARK})])]}),
        new TableCell({shading:{fill:i%2===0?LT_RED:"FEFEFE",type:ShadingType.CLEAR},borders:topBot(),margins:{top:100,bottom:100,left:140,right:140},width:{size:2640,type:WidthType.DXA},children:[p([r(cost,{size:18,color:RED,bold:true})])]}),
      ]}))
    ]
  }),
  spacer(60),
  singleCell([
    p([r("TOTAL ESTIMATED UNDISCLOSED ISSUES:",{bold:true,size:20,color:RED})]),
    p([r("$23,700 – $35,500",{bold:true,size:30,color:RED})],{spacing:{before:60}}),
  ],LT_RED,{top:sb(RED,4),bottom:sb(RED,4),left:sb(RED,4),right:sb(RED,4)},{top:140,bottom:140,left:240,right:240}),
];

// ── OUTCOME ───────────────────────────────────────────────────────────────────
const outcome = [
  spacer(80),
  singleCell([p([r("THE OUTCOME",{bold:true,size:22,color:WHITE})])],GREEN,allNone,{top:120,bottom:120,left:240,right:240}),
  spacer(80),
  p([r("Armed with the Opincar Condition Intelligence Report, the buyer went back to the seller with documented, itemized evidence of the undisclosed issues. The seller, faced with a specific and credible counter, agreed to a price reduction.",{size:20,color:DARK})]),
  spacer(60),
  new Table({
    width:{size:9360,type:WidthType.DXA},columnWidths:[3120,3120,3120],
    rows:[new TableRow({children:[
      new TableCell({shading:{fill:LT_GRN,type:ShadingType.CLEAR},borders:{top:sb(GREEN,4),bottom:sb(),left:sb(GREEN,4),right:sb()},margins:{top:140,bottom:140,left:180,right:180},width:{size:3120,type:WidthType.DXA},
        children:[p([r("Original Asking Price",{bold:true,size:18,color:GREEN})]),p([r("$185,000",{bold:true,size:26,color:DARK})],{spacing:{before:40}})]}),
      new TableCell({shading:{fill:LT_GRN,type:ShadingType.CLEAR},borders:{top:sb(GREEN,4),bottom:sb(),left:nb(),right:sb()},margins:{top:140,bottom:140,left:180,right:180},width:{size:3120,type:WidthType.DXA},
        children:[p([r("Price After Renegotiation",{bold:true,size:18,color:GREEN})]),p([r("$163,000",{bold:true,size:26,color:DARK})],{spacing:{before:40}})]}),
      new TableCell({shading:{fill:LT_GRN,type:ShadingType.CLEAR},borders:{top:sb(GREEN,4),bottom:sb(),left:nb(),right:sb(GREEN,4)},margins:{top:140,bottom:140,left:180,right:180},width:{size:3120,type:WidthType.DXA},
        children:[p([r("Buyer's Net Savings",{bold:true,size:18,color:GREEN})]),p([r("$22,000 off + full transparency",{bold:true,size:20,color:DARK})],{spacing:{before:40}})]}),
    ]})]
  }),
  spacer(60),
  p([r("The $500 cost of the Condition Intelligence Report returned $22,000 in negotiated savings — a 44x return. The buyer also entered the purchase with a clear maintenance roadmap and budget for the issues that would need to be addressed, rather than discovering them after the wire cleared.",{size:20,color:DARK,bold:true})]),
