{"language": "javascript", "code": "const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, BorderStyle, WidthType, ShadingType, LevelFormat,
} = require('docx');
const fs = require('fs');

const NAVY   = "1C2B4A";
const STEEL  = "2E6DA4";
const GOLD   = "C9922A";
const GREEN  = "1A5C36";
const LT_BLUE= "D9E8F5";
const LT_GRN = "D5EEE0";
const LT_GOLD= "FAF0DC";
const LT_GRAY= "F2F4F6";
const WHITE  = "FFFFFF";
const DARK   = "1E2A35";
const MID    = "445566";

const nb = () => ({ style: BorderStyle.NONE, size: 0, color: WHITE });
const sb = (c="CCCCCC",sz=1) => ({ style: BorderStyle.SINGLE, size: sz, color: c });
const allNone = { top:nb(),bottom:nb(),left:nb(),right:nb() };
const allThin  = { top:sb(),bottom:sb(),left:sb(),right:sb() };
const topBot = (c="CCCCCC") => ({ top:sb(c),bottom:sb(c),left:nb(),right:nb() });
const bottomOnly = (c="CCCCCC",sz=1) => ({ top:nb(),bottom:sb(c,sz),left:nb(),right:nb() });

function r(text,opts={}) { return new TextRun({text,font:"Arial",...opts}); }
function p(children,opts={}) {
  return new Paragraph({children:Array.isArray(children)?children:[r(children,{size:20,color:DARK})],...opts});
}
function spacer(sz=120) { return new Paragraph({spacing:{before:sz,after:sz},children:[r("")]}); }

function singleCell(children,fill,borders,margins={top:140,bottom:140,left:220,right:220}) {
  return new Table({
    width:{size:9360,type:WidthType.DXA},columnWidths:[9360],
    rows:[new TableRow({children:[new TableCell({
      shading:{fill,type:ShadingType.CLEAR},borders,margins,
      width:{size:9360,type:WidthType.DXA},
      children:Array.isArray(children)?children:[children]
    })]})]
  });
}

function kvRow(label,value,fill=LT_GRAY,bold=false) {
  return new TableRow({children:[
    new TableCell({shading:{fill,type:ShadingType.CLEAR},borders:topBot(),margins:{top:80,bottom:80,left:160,right:160},width:{size:2880,type:WidthType.DXA},
      children:[p([r(label,{size:19,color:MID,bold:true})])]}),
    new TableCell({shading:{fill,type:ShadingType.CLEAR},borders:topBot(),margins:{top:80,bottom:80,left:160,right:160},width:{size:6480,type:WidthType.DXA},
      children:[p([r(value,{size:19,color:DARK,bold})])]}),
  ]});
}

function machineSection(num, make, model, year, serial, hours, condition, fmvLow, fmvHigh, notes, comparables) {
  const condColor = condition >= 7 ? GREEN : condition >= 5 ? GOLD : "AA2222";
  const condFill  = condition >= 7 ? LT_GRN : condition >= 5 ? LT_GOLD : "FAEAEA";
  return [
    spacer(60),
    singleCell([
      p([
        r(`UNIT ${num}  `, {bold:true,size:18,color:GOLD}),
        r(`${year} ${make} ${model}`, {bold:true,size:22,color:WHITE}),
      ]),
    ],NAVY,allNone,{top:120,bottom:120,left:220,right:220}),
    spacer(40),
    new Table({
      width:{size:9360,type:WidthType.DXA},columnWidths:[6000,3360],
      rows:[new TableRow({children:[
        // Left: specs table
        new TableCell({
          shading:{fill:WHITE,type:ShadingType.CLEAR},
          borders:{top:nb(),bottom:nb(),left:nb(),right:sb("DDDDDD")},
          margins:{top:0,bottom:0,left:0,right:160},
          width:{size:6000,type:WidthType.DXA},
