const nb = () => ({ style: BorderStyle.NONE, size: 0, color: WHITE });
const sb = (c="CCCCCC",sz=1) => ({ style: BorderStyle.SINGLE, size: sz, color: c });
const allNone = { top:nb(),bottom:nb(),left:nb(),right:nb() };
const allThin  = { top:sb(),bottom:sb(),left:sb(),right:sb() };
const topBot = (c="CCCCCC") => ({ top:sb(c),bottom:sb(c),left:nb(),right:nb() });

function r(text,opts={}) { return new TextRun({text,font:"Arial",...opts}); }
function p(children,opts={}) {
  return new Paragraph({children:Array.isArray(children)?children:[r(children,{size:20,color:DARK})],...opts});
}
function spacer(sz=120) { return new Paragraph({spacing:{before:sz,after:sz},children:[r("")]}); }
function bullet(text,color=DARK,bold=false) {
  return new Paragraph({numbering:{reference:"bullets",level:0},spacing:{before:50,after:50},children:[r(text,{size:19,color,bold})]});
}
function singleCell(children,fill,borders,margins={top:140,bottom:140,left:220,right:220}) {
  return new Table({
    width:{size:9360,type:WidthType.DXA},columnWidths:[9360],
    rows:[new TableRow({children:[new TableCell({
      shading:{fill,type:ShadingType.CLEAR},borders,margins,
      width:{size:9360,type:WidthType.DXA},
      children:Array.isArray(children)?children:[children]
    })]})]
  });
}

function findingRow(category, rating, detail, costLow, costHigh, i) {
  const ratingColor = rating==="PASS" ? GREEN : rating==="CAUTION" ? AMBER : RED;
  const ratingFill  = rating==="PASS" ? LT_GRN : rating==="CAUTION" ? LT_AMB : LT_RED;
  const rowFill = i%2===0 ? LT_GRAY : WHITE;
  return new TableRow({children:[
    new TableCell({shading:{fill:rowFill,type:ShadingType.CLEAR},borders:topBot(),margins:{top:100,bottom:100,left:140,right:140},width:{size:2200,type:WidthType.DXA},
      children:[p([r(category,{size:18,color:DARK,bold:true})])]}),
    new TableCell({shading:{fill:ratingFill,type:ShadingType.CLEAR},borders:topBot(),margins:{top:100,bottom:100,left:140,right:140},width:{size:900,type:WidthType.DXA},
      children:[p([r(rating,{size:17,color:ratingColor,bold:true})],{alignment:AlignmentType.CENTER})]}),
    new TableCell({shading:{fill:rowFill,type:ShadingType.CLEAR},borders:topBot(),margins:{top:100,bottom:100,left:140,right:140},width:{size:4460,type:WidthType.DXA},
      children:[p([r(detail,{size:18,color:DARK})])]}),
    new TableCell({shading:{fill:rowFill,type:ShadingType.CLEAR},borders:topBot(),margins:{top:100,bottom:100,left:140,right:140},width:{size:1800,type:WidthType.DXA},
      children:[p([r(costLow===0&&costHigh===0?"—":`$${costLow.toLocaleString()} \u2013 $${costHigh.toLocaleString()}`,{size:18,color:costLow===0?MID:RED,bold:costLow>0})],{alignment:AlignmentType.CENTER})]}),
  ]});
}

