const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, BorderStyle, WidthType, ShadingType, LevelFormat,
} = require('docx');
const fs = require('fs');

// ── COLORS ────────────────────────────────────────────────────────────────────
const NAVY    = "1C2B4A";
const STEEL   = "2E6DA4";
const GOLD    = "C9922A";
const GREEN   = "1A5C36";
const PURPLE  = "4A2070";
const LT_BLUE = "D9E8F5";
const LT_GRN  = "D5EEE0";
const LT_GOLD = "FAF0DC";
const LT_PURP = "EDE5F5";
const LT_GRAY = "F2F4F6";
const WHITE   = "FFFFFF";
const DARK    = "1E2A35";
const MID     = "445566";

// ── HELPERS ───────────────────────────────────────────────────────────────────
const nb  = () => ({ style: BorderStyle.NONE, size: 0, color: WHITE });
const sb  = (c="CCCCCC",sz=1) => ({ style: BorderStyle.SINGLE, size: sz, color: c });
const none = { top:nb(),bottom:nb(),left:nb(),right:nb() };
const gray = { top:sb(),bottom:sb(),left:sb(),right:sb() };
const tb   = (c="CCCCCC") => ({ top:sb(c),bottom:sb(c),left:nb(),right:nb() });
const bot  = (c="CCCCCC",sz=1) => ({ top:nb(),bottom:sb(c,sz),left:nb(),right:nb() });

function r(text,o={}) { return new TextRun({text,font:"Arial",...o}); }
function p(kids,o={}) {
  return new Paragraph({
    children: Array.isArray(kids) ? kids : [r(kids,{size:20,color:DARK})], ...o
  });
}
function sp(sz=100) { return p([r("")],{spacing:{before:sz,after:sz}}); }

function bul(text,color=DARK,bold=false) {
  return new Paragraph({
    numbering:{reference:"bullets",level:0},
    spacing:{before:50,after:50},
    children:[r(text,{size:20,color,bold})]
  });
}
function num(text,bold=false) {
  return new Paragraph({
    numbering:{reference:"numbers",level:0},
    spacing:{before:70,after:70},
    children:[r(text,{size:20,color:DARK,bold})]
  });
}

function box(kids,fill,borders,pad={top:160,bottom:160,left:240,right:240}) {
  return new Table({
    width:{size:9360,type:WidthType.DXA}, columnWidths:[9360],
    rows:[new TableRow({children:[new TableCell({
      shading:{fill,type:ShadingType.CLEAR}, borders, margins:pad,
      width:{size:9360,type:WidthType.DXA},
      children: Array.isArray(kids)?kids:[kids]
    })]})]
  });
}

function divider(color=STEEL) {
  return new Paragraph({
    border:{bottom:{style:BorderStyle.SINGLE,size:6,color,space:4}},
    spacing:{before:200,after:60},
    children:[r("")]
  });
}

function sectionHeader(label, fill=NAVY) {
  return box([p([r(label,{bold:true,size:24,color:WHITE})])], fill, none, {top:120,bottom:120,left:240,right:240});
}

function stepBox(num, title, body_paragraphs) {
  return new Table({
    width:{size:9360,type:WidthType.DXA}, columnWidths:[720,8640],
    rows:[new TableRow({children:[
      new TableCell({
        shading:{fill:NAVY,type:ShadingType.CLEAR}, borders:none,
        margins:{top:120,bottom:120,left:120,right:120},
        width:{size:720,type:WidthType.DXA},
        children:[p([r(num,{bold:true,size:26,color:WHITE})],{alignment:AlignmentType.CENTER})]
      }),
      new TableCell({
        shading:{fill:LT_BLUE,type:ShadingType.CLEAR},
        borders:{top:nb(),bottom:sb("AAAAAA"),left:nb(),right:nb()},
        margins:{top:120,bottom:120,left:200,right:200},
        width:{size:8640,type:WidthType.DXA},
        children:[
          p([r(title,{bold:true,size:21,color:NAVY})],{spacing:{before:0,after:60}}),
          ...body_paragraphs
        ]
      })
    ]})]
  });
}

function twoCol(leftKids, rightKids, lw=4680, rw=4680, fill=LT_GRAY) {
  return new Table({
    width:{size:9360,type:WidthType.DXA}, columnWidths:[lw,rw],
    rows:[new TableRow({children:[
      new TableCell({
        shading:{fill,type:ShadingType.CLEAR},
        borders:{top:nb(),bottom:nb(),left:nb(),right:sb("DDDDDD")},
        margins:{top:140,bottom:140,left:200,right:200},
        width:{size:lw,type:WidthType.DXA}, children:leftKids
      }),
      new TableCell({
        shading:{fill:WHITE,type:ShadingType.CLEAR},
        borders:{top:nb(),bottom:nb(),left:nb(),right:nb()},
        margins:{top:140,bottom:140,left:200,right:200},
        width:{size:rw,type:WidthType.DXA}, children:rightKids
      })
    ]})]
  });
}

function scriptBox(intro, script) {
  return box([
    p([r("WORD-FOR-WORD SCRIPT",{bold:true,size:18,color:STEEL})]),
    p([r(intro,{size:18,color:MID,italics:true})],{spacing:{before:40,after:80}}),
    p([r(script,{size:20,color:DARK,italics:true})]),
  ], LT_BLUE, {top:sb(STEEL,4),bottom:sb("AAAAAA"),left:sb(STEEL,4),right:sb("AAAAAA")},{top:160,bottom:160,left:240,right:240});
}

function lenderRow(name, type, abl, location, contact, i) {
  const fill = i%2===0 ? LT_GRAY : WHITE;
  return new TableRow({children:[
    new TableCell({shading:{fill,type:ShadingType.CLEAR},borders:tb(),margins:{top:80,bottom:80,left:120,right:120},width:{size:2200,type:WidthType.DXA},children:[p([r(name,{size:18,color:NAVY,bold:true})])]}),
    new TableCell({shading:{fill,type:ShadingType.CLEAR},borders:tb(),margins:{top:80,bottom:80,left:120,right:120},width:{size:1600,type:WidthType.DXA},children:[p([r(type,{size:17,color:MID})])]}),
    new TableCell({shading:{fill,type:ShadingType.CLEAR},borders:tb(),margins:{top:80,bottom:80,left:120,right:120},width:{size:1160,type:WidthType.DXA},children:[p([r(abl,{size:17,color:abl==="Yes"?GREEN:MID,bold:abl==="Yes"})],{alignment:AlignmentType.CENTER})]}),
    new TableCell({shading:{fill,type:ShadingType.CLEAR},borders:tb(),margins:{top:80,bottom:80,left:120,right:120},width:{size:1600,type:WidthType.DXA},children:[p([r(location,{size:17,color:DARK})])]}),
    new TableCell({shading:{fill,type:ShadingType.CLEAR},borders:tb(),margins:{top:80,bottom:80,left:120,right:120},width:{size:2800,type:WidthType.DXA},children:[p([r(contact,{size:17,color:DARK})])]}),
  ]});
}

// ════════════════════════════════════════════════════════════════════════════
// DOCUMENT
// ════════════════════════════════════════════════════════════════════════════

const doc = new Document({
  numbering:{config:[
    {reference:"bullets",levels:[{level:0,format:LevelFormat.BULLET,text:"\u2022",alignment:AlignmentType.LEFT,style:{paragraph:{indent:{left:720,hanging:360}}}}]},
    {reference:"numbers",levels:[{level:0,format:LevelFormat.DECIMAL,text:"%1.",alignment:AlignmentType.LEFT,style:{paragraph:{indent:{left:720,hanging:360}}}}]},
  ]},
  styles:{
    default:{document:{run:{font:"Arial",size:20,color:DARK}}},
    paragraphStyles:[
      {id:"Heading1",name:"Heading 1",basedOn:"Normal",next:"Normal",quickFormat:true,run:{size:32,bold:true,font:"Arial"},paragraph:{spacing:{before:240,after:120},outlineLevel:0}},
    ]
  },
  sections:[{
    properties:{page:{size:{width:12240,height:15840},margin:{top:1008,right:1152,bottom:1008,left:1152}}},
    children:[

      // ── COVER ──────────────────────────────────────────────────────────────
      box([
        p([r("OPINCAR MACHINERY",{bold:true,size:22,color:"7FA8C9"})],{alignment:AlignmentType.CENTER,spacing:{before:0,after:80}}),
        p([r("Bank Lender Acquisition Guide",{bold:true,size:44,color:WHITE})],{alignment:AlignmentType.CENTER}),
        p([r("How to Find, Approach, and Convert Commercial Lenders into Recurring Valuation Clients",{size:21,color:"AAC8E8",italics:true})],{alignment:AlignmentType.CENTER,spacing:{before:100,after:80}}),
        p([r("A Step-by-Step Prospecting Playbook for TJ Opincar  \u00B7  February 2026",{size:18,color:"7FA8C9"})],{alignment:AlignmentType.CENTER}),
      ],NAVY,none,{top:280,bottom:280,left:360,right:360}),

      sp(120),
      box([
        p([r("The opportunity is real and it\u2019s right in front of you.",{bold:true,size:22,color:NAVY})],{alignment:AlignmentType.CENTER}),
        sp(60),
        p([r("Commercial lenders who finance manufacturing companies need equipment valuations constantly. Most of them use slow, expensive generalist appraisers who have never actually bought or sold a CNC machine in their lives. TJ Opincar has 25+ years of active market experience and can deliver faster, more accurate reports at competitive pricing. The gap between what lenders need and what they currently get is TJ\u2019s entire business opportunity.",{size:20,color:DARK})],{alignment:AlignmentType.CENTER}),
      ],LT_GOLD,{top:sb(GOLD,4),bottom:sb(GOLD,4),left:sb(GOLD,4),right:sb(GOLD,4)},{top:180,bottom:180,left:280,right:280}),

      sp(80),

      // ── WHO YOU'RE TARGETING ───────────────────────────────────────────────
      divider(),
      sectionHeader("PART 1:  WHO YOU ARE TARGETING"),
      sp(80),

      p([r("There are five distinct types of lenders who regularly need industrial machinery valuations. Each has slightly different needs, urgency, and decision-making dynamics. Understanding the difference before you make the call will dramatically improve TJ\u2019s success rate.",{size:20,color:DARK})]),
      sp(80),

      // Type 1
      box([
        p([r("TYPE 1  \u2014  Asset-Based Lenders (ABL)",{bold:true,size:22,color:NAVY})]),
        sp(40),
        twoCol([
          p([r("What they do:",{bold:true,size:19,color:STEEL})],{spacing:{before:0,after:40}}),
          p([r("Make revolving credit lines and term loans to manufacturers and industrial companies, secured by accounts receivable, inventory, and equipment. The equipment on a client\u2019s shop floor IS their collateral \u2014 and they need to know what it\u2019s worth before, during, and after making the loan.",{size:19,color:DARK})]),
          sp(60),
          p([r("Why they need TJ:",{bold:true,size:19,color:STEEL})],{spacing:{before:0,after:40}}),
          p([r("ABL lenders do periodic \u2018field exams\u2019 and collateral audits. Every time a manufacturing borrower adds, removes, or refinances equipment, the lender needs an updated value. This is recurring work, not one-time.",{size:19,color:DARK})]),
        ],[
          p([r("Key Titles to Target:",{bold:true,size:19,color:STEEL})],{spacing:{before:0,after:40}}),
          bul("Senior Relationship Manager, ABL"),
          bul("Portfolio Manager / Credit Analyst"),
          bul("Business Development Officer, Asset-Based Lending"),
          bul("Field Examiner (they audit the collateral)"),
          bul("VP, Commercial Finance"),
          sp(60),
          p([r("Frequency of Need: HIGH",{bold:true,size:19,color:GREEN})]),
          p([r("Every active manufacturing borrower = recurring valuation work.",{size:18,color:DARK,italics:true})],{spacing:{before:20}}),
        ],4800,4560,LT_GRAY),
      ],LT_BLUE,{top:sb(STEEL,4),bottom:sb("BBBBBB"),left:sb(STEEL,4),right:sb("BBBBBB")},{top:160,bottom:160,left:220,right:220}),

      sp(80),

      // Type 2
      box([
        p([r("TYPE 2  \u2014  SBA 7(a) and SBA 504 Lenders",{bold:true,size:22,color:NAVY})]),
        sp(40),
        twoCol([
          p([r("What they do:",{bold:true,size:19,color:STEEL})],{spacing:{before:0,after:40}}),
          p([r("Originate SBA-guaranteed loans for small manufacturers buying equipment. SBA 504 loans specifically finance \u2018long-term machinery and equipment with a useful remaining life of 10+ years.\u2019 Every SBA equipment loan requires documentation of the collateral value \u2014 that\u2019s the valuation.",{size:19,color:DARK})]),
          sp(60),
          p([r("Why they need TJ:",{bold:true,size:19,color:STEEL})],{spacing:{before:0,after:40}}),
          p([r("SBA lenders process dozens of equipment loans per month. They need fast, credible FMV numbers \u2014 especially on used machinery where price guides don\u2019t reflect actual market conditions. TJ\u2019s 48-hour turnaround is a direct competitive advantage vs. traditional appraisers with 3-week queues.",{size:19,color:DARK})]),
        ],[
          p([r("Key Titles to Target:",{bold:true,size:19,color:STEEL})],{spacing:{before:0,after:40}}),
          bul("SBA Lender / SBA Business Development Officer"),
          bul("Commercial Loan Officer (equipment focus)"),
          bul("VP, SBA Lending"),
          bul("CDC (Certified Development Company) Loan Officer"),
          sp(60),
          p([r("Frequency of Need: HIGH",{bold:true,size:19,color:GREEN})]),
          p([r("Active SBA lenders close 5\u201320 equipment loans per month.",{size:18,color:DARK,italics:true})],{spacing:{before:20}}),
        ],4800,4560,LT_GRAY),
      ],LT_BLUE,{top:sb(STEEL,4),bottom:sb("BBBBBB"),left:sb(STEEL,4),right:sb("BBBBBB")},{top:160,bottom:160,left:220,right:220}),

      sp(80),

      // Type 3
      box([
        p([r("TYPE 3  \u2014  Equipment Finance & Leasing Companies",{bold:true,size:22,color:NAVY})]),
        sp(40),
        twoCol([
          p([r("What they do:",{bold:true,size:19,color:STEEL})],{spacing:{before:0,after:40}}),
          p([r("Provide equipment loans and leases directly to manufacturers. Unlike banks, they are often faster-moving and more specialized. They need FMV on used equipment to determine the loan-to-value ratio, especially when financing used machinery from private sellers or dealers.",{size:19,color:DARK})]),
          sp(60),
          p([r("Why they need TJ:",{bold:true,size:19,color:STEEL})],{spacing:{before:0,after:40}}),
          p([r("When a manufacturer wants to finance a used boring mill or machining center purchased from a private seller or at auction, the equipment finance company needs an independent value. TJ is the only appraiser who can tell them not just the value, but exactly what that specific machine is worth in today\u2019s market.",{size:19,color:DARK})]),
        ],[
          p([r("Key Titles to Target:",{bold:true,size:19,color:STEEL})],{spacing:{before:0,after:40}}),
          bul("Credit Officer / Credit Manager"),
          bul("Business Development Manager"),
          bul("Portfolio Manager"),
          bul("VP, Equipment Finance"),
          sp(60),
          p([r("Frequency of Need: MEDIUM-HIGH",{bold:true,size:19,color:GOLD})]),
          p([r("Every deal involving used machinery needs a value.",{size:18,color:DARK,italics:true})],{spacing:{before:20}}),
        ],4800,4560,LT_GRAY),
      ],LT_BLUE,{top:sb(STEEL,4),bottom:sb("BBBBBB"),left:sb(STEEL,4),right:sb("BBBBBB")},{top:160,bottom:160,left:220,right:220}),

