        bul("The FFIEC National Information Center (ffiec.gov/nicpubweb) lists all bank holding companies and their locations \u2014 useful for identifying every branch of a commercial bank in your region"),
      ],LT_GRN,{top:sb(GREEN,4),bottom:sb("AAAAAA"),left:sb(GREEN,4),right:sb("AAAAAA")},{top:160,bottom:160,left:220,right:220}),

      sp(80),

      // Source 3
      box([
        p([r("SOURCE 3  \u2014  LinkedIn Sales Navigator (TJ\u2019s Most Powerful Tool)",{bold:true,size:21,color:NAVY})]),
        p([r("linkedin.com/sales  \u00B7  ~$100/month for Sales Navigator",{size:19,color:STEEL,italics:true})],{spacing:{before:40,after:80}}),
        p([r("LinkedIn is where commercial lenders actually have profiles and can be directly messaged. Sales Navigator allows highly specific filtering that makes this the most efficient prospecting tool TJ has for this audience.",{size:19,color:DARK})]),
        sp(60),
        p([r("Exact search filters to use:",{bold:true,size:19,color:GREEN})]),
        bul("Job Title: \u2018Commercial Loan Officer\u2019 OR \u2018Asset Based Lending\u2019 OR \u2018Equipment Finance\u2019 OR \u2018SBA Lender\u2019 OR \u2018Portfolio Manager\u2019"),
        bul("Industry: Banking, Financial Services"),
        bul("Geography: Tennessee, Kentucky, Alabama, Georgia, Ohio, Indiana"),
        bul("Company Size: 51\u201310,000 employees (captures both regional banks and national ABL lenders)"),
        sp(60),
        p([r("This search will return 200\u2013500 names. TJ sends 10\u201315 personalized messages per week. Not mass outreach \u2014 personal notes referencing their specific institution and role.",{size:19,color:DARK,italics:true})]),
      ],LT_GRN,{top:sb(GREEN,4),bottom:sb("AAAAAA"),left:sb(GREEN,4),right:sb("AAAAAA")},{top:160,bottom:160,left:220,right:220}),

      sp(80),

      // Source 4
      box([
        p([r("SOURCE 4  \u2014  Tennessee Bankers Association & State Banking Associations",{bold:true,size:21,color:NAVY})]),
        p([r("tnbankers.org  \u00B7  Also: Kentucky Bankers Assoc., Alabama Bankers Assoc., Georgia Bankers Assoc.",{size:19,color:STEEL,italics:true})],{spacing:{before:40,after:80}}),
        p([r("State banking associations publish member directories of every chartered bank in the state, along with their commercial lending contacts. These are the mid-size and community banks that write equipment term loans for local manufacturers every day.",{size:19,color:DARK})]),
        sp(60),
        p([r("How to use it:",{bold:true,size:19,color:GREEN})]),
        bul("Go to tnbankers.org and look for their Member Directory or Resources section"),
        bul("Pull a list of member banks \u2014 focus on those with $500M\u2013$5B in assets (small enough to be relationship-driven, large enough to have active commercial lending teams)"),
        bul("Cross-reference on LinkedIn to find the VP of Commercial Lending or Commercial Relationship Manager at each bank"),
        bul("Join the Tennessee Bankers Association\u2019s associate member program \u2014 this allows TJ to attend events and get access to networking with the exact people he wants to reach"),
      ],LT_GRN,{top:sb(GREEN,4),bottom:sb("AAAAAA"),left:sb(GREEN,4),right:sb("AAAAAA")},{top:160,bottom:160,left:220,right:220}),

      sp(80),

      // Source 5
      box([
        p([r("SOURCE 5  \u2014  ABL Advisor Directory",{bold:true,size:21,color:NAVY})]),
        p([r("abladvisor.com/industry-directory",{size:19,color:STEEL,italics:true})],{spacing:{before:40,after:80}}),
        p([r("ABL Advisor is the trade publication for the asset-based lending world. Their industry directory lists ABL lenders, field examiners, turnaround professionals, and service providers by geography and specialty. It\u2019s free to browse and is one of the most targeted lists available.",{size:19,color:DARK})]),
        sp(60),
        p([r("How to use it:",{bold:true,size:19,color:GREEN})]),
        bul("Go to abladvisor.com/industry-directory and filter by lender type and geography"),
        bul("Note every ABL lender with Southeast U.S. coverage"),
        bul("Read their recent news and deal announcements \u2014 ABL Advisor publishes press releases when lenders close new deals with manufacturers. These are warm leads."),
        bul("Subscribe to ABL Advisor\u2019s free email newsletter \u2014 it will surface new lender activity in TJ\u2019s market regularly"),
      ],LT_GRN,{top:sb(GREEN,4),bottom:sb("AAAAAA"),left:sb(GREEN,4),right:sb("AAAAAA")},{top:160,bottom:160,left:220,right:220}),

      sp(80),

      // Source 6
      box([
        p([r("SOURCE 6  \u2014  UCC Filings (Public Record of Equipment-Secured Loans)",{bold:true,size:21,color:NAVY})]),
        p([r("Tennessee Secretary of State: sos.tn.gov  \u00B7  Also available in KY, AL, GA, OH",{size:19,color:STEEL,italics:true})],{spacing:{before:40,after:80}}),
        p([r("This is TJ\u2019s most powerful and underused research tool. When a bank makes a loan secured by equipment, they file a UCC-1 financing statement with the state Secretary of State. These are public records and they show exactly which banks are lending against manufacturing equipment, in what counties, and to which companies.",{size:19,color:DARK})]),
        sp(60),
        p([r("How to use it:",{bold:true,size:19,color:GREEN})]),
        bul("Go to sos.tn.gov and search UCC filings for \u2018CNC\u2019 or \u2018machining\u2019 or \u2018boring mill\u2019 as collateral descriptions"),
        bul("Each filing lists: the Secured Party (the lender), the Debtor (the manufacturer), and a collateral description"),
        bul("Look for lenders who appear repeatedly \u2014 those are active equipment lenders who need valuations regularly"),
        bul("Use this data to build a warm call list: \u2018I noticed your institution has several active equipment-secured loans with manufacturers in the region. I wanted to introduce Opincar\u2019s valuation service.\u2019"),
        sp(60),
        p([r("This approach is highly targeted, factual, and impressive. Most competitors will never think to use UCC data this way.",{size:19,color:DARK,bold:true})])
      ],LT_GRN,{top:sb(GREEN,4),bottom:sb("AAAAAA"),left:sb(GREEN,4),right:sb("AAAAAA")},{top:160,bottom:160,left:220,right:220}),

      sp(120),

      // ── TARGET LENDER LIST ─────────────────────────────────────────────────
      divider(),
      sectionHeader("PART 3:  TARGET LENDER LIST \u2014 START HERE"),
      sp(80),

      p([r("The following institutions are confirmed to have active commercial equipment lending or ABL operations in TJ\u2019s target geography (TN, KY, AL, GA, OH). This is TJ\u2019s Day 1 prospecting list. Names and direct contacts should be confirmed via LinkedIn and the sources above before reaching out.",{size:20,color:DARK})]),
      sp(60),

      new Table({
        width:{size:9360,type:WidthType.DXA},
        columnWidths:[2200,1600,1160,1600,2800],
        rows:[
          new TableRow({children:[
            ...[["INSTITUTION",2200],["TYPE",1600],["ABL?",1160],["LOCATION",1600],["WHO TO ASK FOR",2800]].map(([h,w])=>
              new TableCell({shading:{fill:NAVY,type:ShadingType.CLEAR},borders:none,margins:{top:80,bottom:80,left:120,right:120},width:{size:w,type:WidthType.DXA},
                children:[p([r(h,{bold:true,size:17,color:WHITE})])]})
            )
          ]}),
          lenderRow("Renasant Bank","Regional Bank / ABL","Yes","Southeast U.S.","Dir. of Asset Based Lending",0),
          lenderRow("Cadence Bank","Regional Bank / ABL","Yes","Nashville + Southeast","VP, Asset-Based Lending",1),
          lenderRow("First Citizens Bank","National / ABL","Yes","Nashville, Knoxville","Commercial Finance Division",2),
          lenderRow("Tennessee Commerce Bank","Community Bank","No","Franklin, TN","VP, Commercial Lending",3),
          lenderRow("Avenue Bank (Pinnacle)","Regional Bank","No","Nashville, TN","Commercial Relationship Mgr",4),
          lenderRow("Pinnacle Financial","Regional Bank","No","Nashville + TN","Equipment Loan Officer",5),
          lenderRow("Home Federal Bank TN","Community Bank","No","East TN","Commercial Lending Dept",6),
          lenderRow("BancTennessee","Community Bank","No","TN Multi-location","Commercial Loan Officer",7),
          lenderRow("First Bank (TN)","Regional Bank","No","TN statewide","VP Commercial Banking",8),
          lenderRow("Truist Bank","National / ABL","Yes","Nashville, Memphis","ABL Division \u2014 Southeast",9),
          lenderRow("PNC Bank","National / ABL","Yes","Nashville, Knoxville","Equipment Finance Division",10),
          lenderRow("Fifth Third Bank","National / ABL","Yes","Nashville TN","ABL / Equipment Finance",11),
          lenderRow("Regions Bank","National / ABL","Yes","Birmingham + Southeast","Corporate Banking / ABL",12),
          lenderRow("First Horizon Bank","Regional Bank","No","Memphis + TN","Commercial Relationship Mgr",13),
          lenderRow("Wintrust Business Credit","Non-Bank ABL","Yes","Southeast focus","Senior ABL Officer",14),
          lenderRow("Northpoint Commercial Finance","Non-Bank ABL","Yes","Southeast coverage","Business Dev Manager",15),
          lenderRow("First Bank of the Lake","SBA Specialist","No","National SBA focus","SBA Lending Division",16),
          lenderRow("Tennessee Valley Authority FCU","Credit Union","No","East TN manufacturers","Business Lending Dept",17),
        ]
      }),

      sp(60),
      box([
        p([r("Note: For national banks (Truist, PNC, Fifth Third, Regions), the ABL and Equipment Finance divisions operate separately from retail branches. Always ask specifically for the \u2018commercial lending\u2019 or \u2018asset-based lending\u2019 team, not the general banking number.",{size:18,color:MID,italics:true})]),
      ],LT_GRAY,gray,{top:100,bottom:100,left:180,right:180}),

      sp(120),

      // ── STEP-BY-STEP PROCESS ───────────────────────────────────────────────
      divider(),
      sectionHeader("PART 4:  STEP-BY-STEP ACQUISITION PROCESS"),
      sp(80),

      p([r("This is TJ\u2019s exact weekly system for building his bank lender client base from zero to 10+ recurring relationships. Follow the steps in sequence.",{size:20,color:DARK,bold:true})]),
      sp(80),

      stepBox("1","BUILD YOUR PROSPECT LIST (Week 1 \u2014 One-Time Setup, 3\u20134 Hours)",[
        p([r("Start with the sources in Part 2 and build a spreadsheet with 50\u201375 names. For each entry, capture:",{size:19,color:DARK})],{spacing:{before:0,after:60}}),
        bul("Institution name and type (ABL lender, regional bank, equipment finance company)"),
        bul("Contact name, title, LinkedIn URL, email (if findable), and phone number"),
        bul("Geographic coverage (do they lend to manufacturers in TJ\u2019s region?)"),
        bul("Any notes from UCC filings, ABL Advisor deal announcements, or news"),
        sp(60),
        p([r("Prioritize the list in three tiers: Tier 1 (ABL lenders and confirmed equipment finance companies), Tier 2 (regional banks with active commercial lending), Tier 3 (community banks and SBA lenders). Start all outreach with Tier 1.",{size:19,color:DARK,italics:true})]),
      ]),

      sp(40),

      stepBox("2","SEND THE PHYSICAL LETTER FIRST \u2014 NOT AN EMAIL (Week 1, Rolling)",[
        p([r("Industrial and commercial lenders open physical mail. Email from an unknown sender gets deleted. A one-page letter on Opincar letterhead addressed to a specific name and title at a bank creates immediate credibility. Send 10\u201315 letters per week.",{size:19,color:DARK})],{spacing:{before:0,after:80}}),
        p([r("The letter should:",{bold:true,size:19,color:STEEL})],{spacing:{before:0,after:40}}),
        bul("Be addressed to the specific person by name and title"),
        bul("Open with TJ\u2019s 25+ years of experience \u2014 lead with credibility, not sales"),
        bul("Describe the service in 2\u20133 sentences: fast turnaround, active market knowledge, competitive pricing"),
        bul("Include one concrete proof point: 'We recently delivered a 14-machine FMV assessment for a Middle Tennessee bank in under 48 hours'"),
        bul("Close with a single, low-friction CTA: 'I\u2019ll follow up by phone next week. If you\u2019d like to speak sooner, here\u2019s my direct number.'"),
        bul("Include TJ\u2019s one-page capability sheet or the sample valuation report as an enclosure"),
      ]),

      sp(40),

      stepBox("3","FOLLOW UP BY PHONE 5\u20137 DAYS AFTER THE LETTER",[
        p([r("The letter makes the call warm. TJ is not cold-calling \u2014 he\u2019s following up on correspondence. This distinction matters enormously in a conservative banking environment.",{size:19,color:DARK})],{spacing:{before:0,after:60}}),
        p([r("Call protocol:",{bold:true,size:19,color:STEEL})],{spacing:{before:0,after:40}}),
        bul("Call the bank\u2019s main number and ask for the person by name and title"),
        bul("If gatekeeper asks what it\u2019s about: 'I sent him/her a letter about our industrial equipment valuation service for your commercial lending team last week \u2014 just following up'"),
        bul("If voicemail: leave a 20\u201325 second message, state your name, Opincar Machinery, 25 years in CNC equipment, mention the letter, and leave a callback number"),
        bul("If you reach them: use the script in Part 5 below"),
        bul("Call 3 times over 2 weeks before moving on \u2014 lenders are busy, not hostile"),
      ]),

      sp(40),

      stepBox("4","OFFER THE FREE SAMPLE REPORT AS YOUR DOOR-OPENER",[
        p([r("The single most effective tactic for getting a first engagement is offering to run a free or deeply discounted valuation on one machine the lender already knows the value of. This eliminates all perceived risk.",{size:19,color:DARK})],{spacing:{before:0,after:60}}),
        p([r("How to use it in the call:",{bold:true,size:19,color:STEEL})],{spacing:{before:0,after:40}}),
        bul("'If it would be helpful, I\u2019d be glad to run a complimentary valuation on one machine from one of your existing borrowers \u2014 a machine you already know the value of \u2014 so you can compare our process and report quality to what you\u2019re currently using. No cost, no obligation.'"),
        bul("Most lenders will say yes. This is how TJ gets the first report in front of them."),
        bul("Deliver it in under 48 hours. Make it look exactly like the sample report in TJ\u2019s playbook."),
        bul("After delivery, follow up: 'How did that compare to the reports you normally receive?' Let the quality do the selling."),
      ]),

      sp(40),

      stepBox("5","CONFIRM THE RELATIONSHIP AND SET EXPECTATIONS",[
        p([r("Once the free or first paid report lands well, close the ongoing relationship \u2014 don\u2019t let the conversation drift.",{size:19,color:DARK})],{spacing:{before:0,after:60}}),
        p([r("The closing conversation:",{bold:true,size:19,color:STEEL})],{spacing:{before:0,after:40}}),
        bul("'I\u2019d love to be your go-to resource for equipment valuations on manufacturing collateral. Our standard turnaround is 48 hours, our pricing is [X], and you can reach me directly any time. Should I send over a one-page overview you can keep on file?'"),
        bul("Send a simple one-page service sheet with TJ\u2019s contact info, turnaround time, pricing, and machine specialties"),
        bul("Ask: 'Do you have any deals in your pipeline right now where an equipment valuation would be helpful?'"),
        bul("Every 'yes' to that question is a paid engagement within days"),
      ]),

      sp(40),

      stepBox("6","BUILD THE REFERRAL NETWORK INSIDE THE BANK",[
        p([r("One lender at one bank is a start. But banks have entire commercial lending teams. Once TJ has one good relationship inside an institution, he can expand horizontally.",{size:19,color:DARK})],{spacing:{before:0,after:60}}),
        bul("After delivering 2\u20133 reports to a single lender, ask: 'Are there other lenders on your team who also deal with equipment-secured manufacturing loans? I\u2019d love to introduce myself.'"),
        bul("Ask for an introduction via email or a brief in-person visit to the commercial lending floor"),
        bul("One contact at Fifth Third can turn into the entire Middle Tennessee commercial lending team"),
        bul("Offer to do a 20-minute lunch-and-learn for the commercial team: 'What to Look For When Manufacturing Equipment is Your Collateral'"),
      ]),

      sp(40),

      stepBox("7","MAINTAIN THE RELATIONSHIP \u2014 STAY VISIBLE WITHOUT BEING ANNOYING",[
        p([r("Commercial lenders don\u2019t need to hear from TJ every week. But they do need to remember him when an equipment deal crosses their desk.",{size:19,color:DARK})],{spacing:{before:0,after:60}}),
        p([r("Low-effort monthly touchpoints:",{bold:true,size:19,color:STEEL})],{spacing:{before:0,after:40}}),
        bul("Send a one-page \u2018Opincar Market Intelligence\u2019 update once a month via email: brief bullet points on what\u2019s happening in used CNC machinery pricing, notable auction results, or demand trends by machine type"),
        bul("Forward a relevant industry news article twice a quarter with a 2-line personal note"),
        bul("Call at the start of Q1 and Q3 to check in: 'Just checking in \u2014 any equipment-collateral deals I can help you with this quarter?'"),
        bul("Send a handwritten thank-you note when a relationship generates a paid engagement"),
      ]),

      sp(120),

      // ── SCRIPTS ───────────────────────────────────────────────────────────
      divider(),
      sectionHeader("PART 5:  WORD-FOR-WORD SCRIPTS FOR EVERY SITUATION"),
      sp(80),

      p([r("Cold Call \u2014 First Contact (Letter Was Sent)",{bold:true,size:21,color:NAVY})]),
      sp(40),
      scriptBox(
        "When you reach the lender directly after they received the letter:",
        "\u201CHi [Name], this is TJ Opincar with Opincar Machinery in Smyrna. I sent you a letter last week about our industrial equipment valuation service. I\u2019ve been in the heavy CNC machinery business for over 25 years \u2014 buying, selling, and appraising boring mills, machining centers, lathes, and fabrication equipment. I work with a handful of commercial lenders who use us when they need a fast, accurate fair market value on manufacturing equipment collateral. Our standard turnaround is 48 hours \u2014 which tends to be a lot faster than most appraisers those lenders have used before. Do you have two minutes for me to describe how it works, or would it be easier if I just sent over a sample report so you can see the format?\u201D"
      ),

      sp(80),

      p([r("Voicemail Script",{bold:true,size:21,color:NAVY})]),
      sp(40),
      scriptBox(
        "If you reach voicemail \u2014 keep it under 25 seconds:",
        "\u201CHi [Name], this is TJ Opincar with Opincar Machinery \u2014 we\u2019re an industrial CNC machinery dealer with 25+ years in the market, and I sent you a letter last week about our equipment valuation service for commercial lenders. We turn around detailed FMV reports in 48 hours. My direct number is [number]. Happy to send a sample report if that\u2019s easier. Thanks.\u201D"
      ),

      sp(80),

      p([r("Offering the Free Sample During the Call",{bold:true,size:21,color:NAVY})]),
      sp(40),
      scriptBox(
        "When the lender is interested but not ready to commit:",
        "\u201CLet me make this easy. Give me one machine from one of your current borrowers \u2014 something you already know the rough value on \u2014 and let me run a complimentary valuation on it. You\u2019ll see our report format, the level of market detail we include, and our turnaround time. No cost, no obligation. If it\u2019s not better than what you\u2019re currently using, you haven\u2019t lost anything. If it is, we can talk about working together going forward.\u201D"
      ),

      sp(80),

      p([r("Handling the 'We Already Have an Appraiser' Objection",{bold:true,size:21,color:NAVY})]),
      sp(40),
      scriptBox(
        "The most common pushback \u2014 have this ready:",
        "\u201CThat\u2019s great \u2014 and I\u2019m not trying to replace a relationship that\u2019s working. What I\u2019d offer is a faster option for when your regular appraiser has a backlog, or a second opinion when the collateral is specialized industrial equipment that a generalist appraiser might not know as well. I\u2019ve personally bought and sold boring mills, machining centers, and lathes for 25 years \u2014 I\u2019m an active market participant, not someone reading a price guide. That difference shows up in the accuracy of the numbers. The only way to know is to see a report.\u201D"
      ),

      sp(80),

      p([r("LinkedIn Direct Message to a Cold Contact",{bold:true,size:21,color:NAVY})]),
      sp(40),
      scriptBox(
        "Short, personal, no hard sell \u2014 goal is just to open the conversation:",
        "\u201CHi [Name] \u2014 I noticed you\u2019re doing commercial equipment lending at [Bank]. I\u2019ve been in heavy CNC machinery \u2014 boring mills, machining centers, lathes \u2014 for 25+ years, buying and selling actively in the Southeast market. I recently started offering formal equipment valuations for commercial lenders who need fast, accurate FMV on industrial machinery collateral. Turnaround is typically 48 hours. Happy to send a sample report if that\u2019s useful \u2014 no strings attached.\u201D"
      ),

      sp(120),

      // ── WEEKLY RHYTHM ─────────────────────────────────────────────────────
      divider(),
      sectionHeader("PART 6:  TJ\u2019S WEEKLY PROSPECTING RHYTHM"),
      sp(80),

      p([r("Consistency over intensity. This works because TJ does a little bit every week, not a huge push once a quarter. The system below can be done in 3\u20134 hours per week.",{size:20,color:DARK,bold:true})]),
      sp(80),

      new Table({
        width:{size:9360,type:WidthType.DXA},
        columnWidths:[1600,7760],
        rows:[
          new TableRow({children:[
            new TableCell({shading:{fill:NAVY,type:ShadingType.CLEAR},borders:none,margins:{top:80,bottom:80,left:160,right:160},width:{size:1600,type:WidthType.DXA},children:[p([r("WHEN",{bold:true,size:18,color:WHITE})],{alignment:AlignmentType.CENTER})]}),
            new TableCell({shading:{fill:NAVY,type:ShadingType.CLEAR},borders:none,margins:{top:80,bottom:80,left:160,right:160},width:{size:7760,type:WidthType.DXA},children:[p([r("WHAT TJ DOES",{bold:true,size:18,color:WHITE})])]}),
          ]}),
          ...[
            ["Monday\n(30 min)","Research 5 new prospects using LinkedIn, SFNet directory, or ABL Advisor. Add name, title, company, LinkedIn URL, and phone to prospect spreadsheet. Note any context (recent deal announcements, industry they serve, etc.)"],
            ["Tuesday\n(45 min)","Write and mail 5 physical letters using the letter template. Address each one personally. Include the one-page capability sheet as an enclosure. Batch printing and mailing on Tuesdays keeps this from becoming a random task."],
            ["Wednesday\n(45 min)","Make phone follow-up calls to anyone who received a letter 5\u20137 days ago. Goal: reach 2\u20133 people live. Leave voicemails for the rest. Log every call outcome in the spreadsheet."],
            ["Thursday\n(30 min)","Send 5\u20138 LinkedIn messages to new prospects who have not yet received a physical letter. Personal, short, no pitch \u2014 just open a conversation. Connect with anyone who accepts the invite."],
            ["Friday\n(20 min)","Review the week: how many new contacts made, how many sample report offers extended, any paid engagements confirmed. Update the spreadsheet. Plan next week\u2019s 5 new research targets."],
            ["Monthly\n(60 min)","Send the Opincar Market Intelligence email to all active lender contacts (anyone who has engaged or done business). One page, 3\u20135 bullet points on CNC machinery market activity. Keeps TJ visible without being pushy."],
          ].map(([when,what],i) => new TableRow({children:[
            new TableCell({shading:{fill:i%2===0?LT_BLUE:WHITE,type:ShadingType.CLEAR},borders:tb(),margins:{top:100,bottom:100,left:140,right:140},width:{size:1600,type:WidthType.DXA},children:[p([r(when,{bold:true,size:18,color:NAVY})],{alignment:AlignmentType.CENTER})]}),
            new TableCell({shading:{fill:i%2===0?LT_BLUE:WHITE,type:ShadingType.CLEAR},borders:tb(),margins:{top:100,bottom:100,left:140,right:140},width:{size:7760,type:WidthType.DXA},children:[p([r(what,{size:19,color:DARK})])]}),
          ]}))
        ]
      }),

      sp(80),

      box([
        p([r("REALISTIC EXPECTATIONS: At this rhythm, TJ should expect 1\u20132 new paid engagements per month in months 1\u20132, growing to 3\u20135 per month by month 4\u20136 as referrals compound. Ten recurring lender relationships, each sending 2\u20133 valuations per month, is a $20K\u2013$40K/month revenue stream.",{size:20,color:DARK,bold:true})]),
      ],LT_GOLD,{top:sb(GOLD,4),bottom:sb(GOLD,4),left:sb(GOLD,4),right:sb(GOLD,4)},{top:160,bottom:160,left:240,right:240}),

      sp(120),

      // ── CLOSE ─────────────────────────────────────────────────────────────
      box([
        p([r("The commercial lending world is small, relationship-driven, and highly resistant to cold outreach from people they don\u2019t know.",{bold:true,size:22,color:WHITE})],{alignment:AlignmentType.CENTER}),
        sp(80),
        p([r("TJ\u2019s 25 years of active market experience is the entire reason lenders should trust him over a generalist appraiser. The key is leading with that experience in every touchpoint \u2014 the letter, the call, the report, the follow-up. He is not a vendor pitching a service. He is the most knowledgeable CNC machinery expert in the region, offering to make their jobs easier and their loan decisions safer. That framing changes everything.",{size:20,color:"AAC8E8"})],{alignment:AlignmentType.CENTER}),
        sp(80),
        p([r("TJ Opincar  \u00B7  Opincar Machinery  \u00B7  Smyrna, TN  \u00B7  (615) 459-7983  \u00B7  tom@opincarmachinery.com",{size:18,color:"7FA8C9"})],{alignment:AlignmentType.CENTER}),
      ],NAVY,none,{top:240,bottom:240,left:360,right:360}),
    ]
  }]
});

Packer.toBuffer(doc).then(buf => {
  fs.writeFileSync('/home/claude/bank_lender_acquisition_guide.docx', buf);
  console.log('Done!');
});

