{"language": "javascript", "code": "const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, BorderStyle, WidthType, ShadingType, LevelFormat,
} = require('docx');
const fs = require('fs');

// ── COLORS ────────────────────────────────────────────────────────────────────
const NAVY    = "1C2B4A";
const STEEL   = "2E6DA4";
const GOLD    = "C9922A";
const GREEN   = "1A5C36";
const PURPLE  = "4A2070";
const LT_BLUE = "D9E8F5";
const LT_GRN  = "D5EEE0";
const LT_GOLD = "FAF0DC";
const LT_PURP = "EDE5F5";
const LT_GRAY = "F2F4F6";
const WHITE   = "FFFFFF";
const DARK    = "1E2A35";
const MID     = "445566";

// ── HELPERS ───────────────────────────────────────────────────────────────────
const nb  = () => ({ style: BorderStyle.NONE, size: 0, color: WHITE });
const sb  = (c="CCCCCC",sz=1) => ({ style: BorderStyle.SINGLE, size: sz, color: c });
const none = { top:nb(),bottom:nb(),left:nb(),right:nb() };
const gray = { top:sb(),bottom:sb(),left:sb(),right:sb() };
const tb   = (c="CCCCCC") => ({ top:sb(c),bottom:sb(c),left:nb(),right:nb() });
const bot  = (c="CCCCCC",sz=1) => ({ top:nb(),bottom:sb(c,sz),left:nb(),right:nb() });

function r(text,o={}) { return new TextRun({text,font:"Arial",...o}); }
function p(kids,o={}) {
  return new Paragraph({
    children: Array.isArray(kids) ? kids : [r(kids,{size:20,color:DARK})], ...o
  });
}
function sp(sz=100) { return p([r("")],{spacing:{before:sz,after:sz}}); }

function bul(text,color=DARK,bold=false) {
  return new Paragraph({
    numbering:{reference:"bullets",level:0},
    spacing:{before:50,after:50},
    children:[r(text,{size:20,color,bold})]
  });
}
function num(text,bold=false) {
  return new Paragraph({
    numbering:{reference:"numbers",level:0},
    spacing:{before:70,after:70},
    children:[r(text,{size:20,color:DARK,bold})]
  });
}

function box(kids,fill,borders,pad={top:160,bottom:160,left:240,right:240}) {
  return new Table({
    width:{size:9360,type:WidthType.DXA}, columnWidths:[9360],
    rows:[new TableRow({children:[new TableCell({
      shading:{fill,type:ShadingType.CLEAR}, borders, margins:pad,
      width:{size:9360,type:WidthType.DXA},
      children: Array.isArray(kids)?kids:[kids]
    })]})]
  });
}

function divider(color=STEEL) {
  return new Paragraph({
    border:{bottom:{style:BorderStyle.SINGLE,size:6,color,space:4}},
    spacing:{before:200,after:60},
    children:[r("")]
  });
}

function sectionHeader(label, fill=NAVY) {
  return box([p([r(label,{bold:true,size:24,color:WHITE})])], fill, none, {top:120,bottom:120,left:240,right:240});
}

function stepBox(num, title, body_paragraphs) {
  return new Table({
    width:{size:9360,type:WidthType.DXA}, columnWidths:[720,8640],
    rows:[new TableRow({children:[
      new TableCell({
        shading:{fill:NAVY,type:ShadingType.CLEAR}, borders:none,
