const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, BorderStyle, WidthType, ShadingType, LevelFormat,
} = require('docx');
const fs = require('fs');

// ── COLORS ────────────────────────────────────────────────────────────────────
const NAVY    = "1C2B4A";
const STEEL   = "2E6DA4";
const GOLD    = "C9922A";
const GREEN   = "1A5C36";
const PURPLE  = "3D1A6E";
const TEAL    = "0D5C63";
const RED     = "8B1A1A";
const LT_BLUE = "D9E8F5";
const LT_GRN  = "D5EEE0";
const LT_GOLD = "FAF0DC";
const LT_PURP = "EDE5F5";
const LT_TEAL = "D4EDEE";
const LT_GRAY = "F2F4F6";
const WHITE   = "FFFFFF";
const DARK    = "1E2A35";
const MID     = "445566";

const nb  = () => ({ style: BorderStyle.NONE, size: 0, color: WHITE });
const sb  = (c="CCCCCC",sz=1) => ({ style: BorderStyle.SINGLE, size: sz, color: c });
const none = { top:nb(),bottom:nb(),left:nb(),right:nb() };
const gray  = { top:sb(),bottom:sb(),left:sb(),right:sb() };
const tb    = (c="CCCCCC") => ({ top:sb(c),bottom:sb(c),left:nb(),right:nb() });

function r(text,o={}) { return new TextRun({text,font:"Arial",...o}); }
function p(kids,o={}) {
  return new Paragraph({children:Array.isArray(kids)?kids:[r(kids,{size:20,color:DARK})],...o});
}
function sp(sz=100) { return p([r("")],{spacing:{before:sz,after:sz}}); }
function bul(text,color=DARK,bold=false) {
  return new Paragraph({numbering:{reference:"bullets",level:0},spacing:{before:50,after:50},children:[r(text,{size:20,color,bold})]});
}
function subbul(text,color=DARK) {
  return new Paragraph({numbering:{reference:"subbullets",level:0},spacing:{before:40,after:40},children:[r(text,{size:19,color,italics:true})]});
}
function divider(color=STEEL) {
  return new Paragraph({border:{bottom:{style:BorderStyle.SINGLE,size:6,color,space:4}},spacing:{before:200,after:60},children:[r("")]});
}
function box(kids,fill,borders,pad={top:160,bottom:160,left:240,right:240}) {
  return new Table({
    width:{size:9360,type:WidthType.DXA},columnWidths:[9360],
    rows:[new TableRow({children:[new TableCell({
      shading:{fill,type:ShadingType.CLEAR},borders,margins:pad,
      width:{size:9360,type:WidthType.DXA},
      children:Array.isArray(kids)?kids:[kids]
    })]})]
  });
}
function sectionHeader(label,fill=NAVY) {
  return box([p([r(label,{bold:true,size:24,color:WHITE})])],fill,none,{top:120,bottom:120,left:240,right:240});
}
function stepBox(num,title,bodyParagraphs,accentColor=NAVY) {
  return new Table({
    width:{size:9360,type:WidthType.DXA},columnWidths:[760,8600],
    rows:[new TableRow({children:[
      new TableCell({
        shading:{fill:accentColor,type:ShadingType.CLEAR},borders:none,
        margins:{top:120,bottom:120,left:120,right:120},
        width:{size:760,type:WidthType.DXA},
        children:[p([r(num,{bold:true,size:28,color:WHITE})],{alignment:AlignmentType.CENTER})]
      }),
      new TableCell({
        shading:{fill:LT_BLUE,type:ShadingType.CLEAR},
        borders:{top:nb(),bottom:sb("AAAAAA"),left:nb(),right:nb()},
        margins:{top:120,bottom:120,left:200,right:200},
        width:{size:8600,type:WidthType.DXA},
        children:[
          p([r(title,{bold:true,size:22,color:accentColor})],{spacing:{before:0,after:60}}),
          ...bodyParagraphs
        ]
      })
    ]})]
  });
}
function scriptBox(label,script) {
  return box([
    p([r(label,{bold:true,size:18,color:PURPLE})]),
    p([r(script,{size:20,color:DARK,italics:true})],{spacing:{before:80}}),
  ],LT_PURP,{top:sb(PURPLE,4),bottom:sb("BBBBBB"),left:sb(PURPLE,4),right:sb("BBBBBB")},{top:160,bottom:160,left:240,right:240});
}
function peRow(firm,hq,focus,contact,trigger,i) {
  const fill = i%2===0?LT_GRAY:WHITE;
  return new TableRow({children:[
    new TableCell({shading:{fill,type:ShadingType.CLEAR},borders:tb(),margins:{top:80,bottom:80,left:120,right:120},width:{size:2000,type:WidthType.DXA},children:[p([r(firm,{size:18,color:NAVY,bold:true})])]}),
    new TableCell({shading:{fill,type:ShadingType.CLEAR},borders:tb(),margins:{top:80,bottom:80,left:120,right:120},width:{size:1440,type:WidthType.DXA},children:[p([r(hq,{size:17,color:MID})])]}),
    new TableCell({shading:{fill,type:ShadingType.CLEAR},borders:tb(),margins:{top:80,bottom:80,left:120,right:120},width:{size:2200,type:WidthType.DXA},children:[p([r(focus,{size:17,color:DARK})])]}),
    new TableCell({shading:{fill,type:ShadingType.CLEAR},borders:tb(),margins:{top:80,bottom:80,left:120,right:120},width:{size:1960,type:WidthType.DXA},children:[p([r(contact,{size:17,color:STEEL})])]}),
    new TableCell({shading:{fill,type:ShadingType.CLEAR},borders:tb(),margins:{top:80,bottom:80,left:120,right:120},width:{size:1760,type:WidthType.DXA},children:[p([r(trigger,{size:17,color:GREEN,bold:true})])]}),
  ]});
}

// ════════════════════════════════════════════════════════════════════════════
const doc = new Document({
  numbering:{config:[
    {reference:"bullets",levels:[{level:0,format:LevelFormat.BULLET,text:"\u2022",alignment:AlignmentType.LEFT,style:{paragraph:{indent:{left:720,hanging:360}}}}]},
    {reference:"subbullets",levels:[{level:0,format:LevelFormat.BULLET,text:"\u25E6",alignment:AlignmentType.LEFT,style:{paragraph:{indent:{left:1080,hanging:360}}}}]},
    {reference:"numbers",levels:[{level:0,format:LevelFormat.DECIMAL,text:"%1.",alignment:AlignmentType.LEFT,style:{paragraph:{indent:{left:720,hanging:360}}}}]},
  ]},
  styles:{
    default:{document:{run:{font:"Arial",size:20,color:DARK}}},
    paragraphStyles:[{id:"Heading1",name:"Heading 1",basedOn:"Normal",next:"Normal",quickFormat:true,run:{size:32,bold:true,font:"Arial"},paragraph:{spacing:{before:240,after:120},outlineLevel:0}}]
  },
  sections:[{
    properties:{page:{size:{width:12240,height:15840},margin:{top:1008,right:1152,bottom:1008,left:1152}}},
    children:[

      // ── COVER ──────────────────────────────────────────────────────────────
      box([
        p([r("OPINCAR MACHINERY",{bold:true,size:22,color:"7FA8C9"})],{alignment:AlignmentType.CENTER,spacing:{before:0,after:80}}),
        p([r("Private Equity Acquisition Guide",{bold:true,size:44,color:WHITE})],{alignment:AlignmentType.CENTER}),
        p([r("How to Find, Approach, and Become the Go-To Equipment Expert for PE Firms and Portfolio Company Operators",{size:21,color:"AAC8E8",italics:true})],{alignment:AlignmentType.CENTER,spacing:{before:100,after:80}}),
        p([r("TJ Opincar  \u00B7  Opincar Machinery  \u00B7  Smyrna, TN  \u00B7  February 2026",{size:18,color:"7FA8C9"})],{alignment:AlignmentType.CENTER}),
      ],NAVY,none,{top:280,bottom:280,left:360,right:360}),

