const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, BorderStyle, WidthType, ShadingType, LevelFormat,
} = require('docx');
const fs = require('fs');

const NAVY    = "1C2B4A";
const STEEL   = "2E6DA4";
const GOLD    = "C9922A";
const GREEN   = "1A5C36";
const TEAL    = "0D5C63";
const RED     = "8B1A1A";
const LT_BLUE = "D9E8F5";
const LT_GRN  = "D5EEE0";
const LT_GOLD = "FAF0DC";
const LT_TEAL = "D4EDEE";
const LT_GRAY = "F2F4F6";
const WHITE   = "FFFFFF";
const DARK    = "1E2A35";
const MID     = "445566";

const nb  = () => ({ style: BorderStyle.NONE, size: 0, color: WHITE });
const sb  = (c="CCCCCC",sz=1) => ({ style: BorderStyle.SINGLE, size: sz, color: c });
const none = { top:nb(),bottom:nb(),left:nb(),right:nb() };
const allg  = { top:sb(),bottom:sb(),left:sb(),right:sb() };
const tb    = (c="CCCCCC") => ({ top:sb(c),bottom:sb(c),left:nb(),right:nb() });

function r(text,o={}) { return new TextRun({text,font:"Arial",...o}); }
function p(kids,o={}) {
  return new Paragraph({children:Array.isArray(kids)?kids:[r(kids,{size:20,color:DARK})],...o});
}
function sp(sz=100) { return p([r("")],{spacing:{before:sz,after:sz}}); }
function bul(text,color=DARK,bold=false,sz=20) {
  return new Paragraph({numbering:{reference:"bullets",level:0},spacing:{before:50,after:50},children:[r(text,{size:sz,color,bold})]});
}
function divider(color=STEEL) {
  return new Paragraph({border:{bottom:{style:BorderStyle.SINGLE,size:6,color,space:4}},spacing:{before:200,after:60},children:[r("")]});
}
function box(kids,fill,borders,pad={top:160,bottom:160,left:240,right:240}) {
  return new Table({
    width:{size:9360,type:WidthType.DXA},columnWidths:[9360],
    rows:[new TableRow({children:[new TableCell({
      shading:{fill,type:ShadingType.CLEAR},borders,margins:pad,
      width:{size:9360,type:WidthType.DXA},
      children:Array.isArray(kids)?kids:[kids]
    })]})]
  });
}
function sectionHeader(label,fill=NAVY) {
  return box([p([r(label,{bold:true,size:24,color:WHITE})])],fill,none,{top:120,bottom:120,left:240,right:240});
}
function stepBox(num,title,body,accent=NAVY) {
  return new Table({
    width:{size:9360,type:WidthType.DXA},columnWidths:[760,8600],
    rows:[new TableRow({children:[
      new TableCell({
        shading:{fill:accent,type:ShadingType.CLEAR},borders:none,
        margins:{top:120,bottom:120,left:120,right:120},width:{size:760,type:WidthType.DXA},
        children:[p([r(num,{bold:true,size:28,color:WHITE})],{alignment:AlignmentType.CENTER})]
      }),
      new TableCell({
        shading:{fill:LT_BLUE,type:ShadingType.CLEAR},
        borders:{top:nb(),bottom:sb("AAAAAA"),left:nb(),right:nb()},
        margins:{top:120,bottom:120,left:200,right:200},width:{size:8600,type:WidthType.DXA},
        children:[p([r(title,{bold:true,size:22,color:accent})],{spacing:{before:0,after:60}}),...body]
      })
    ]})]
  });
}
function scriptBox(label,script) {
  return box([
    p([r(label,{bold:true,size:18,color:TEAL})]),
    p([r(script,{size:20,color:DARK,italics:true})],{spacing:{before:80}}),
  ],LT_TEAL,{top:sb(TEAL,4),bottom:sb("BBBBBB"),left:sb(TEAL,4),right:sb("BBBBBB")},{top:160,bottom:160,left:240,right:240});
}
function twoCol(leftK,rightK,lw=4680,rw=4680,fillL=LT_GRAY,fillR=WHITE) {
  return new Table({
    width:{size:9360,type:WidthType.DXA},columnWidths:[lw,rw],
    rows:[new TableRow({children:[
      new TableCell({shading:{fill:fillL,type:ShadingType.CLEAR},borders:{top:nb(),bottom:nb(),left:nb(),right:sb("DDDDDD")},margins:{top:140,bottom:140,left:200,right:200},width:{size:lw,type:WidthType.DXA},children:leftK}),
      new TableCell({shading:{fill:fillR,type:ShadingType.CLEAR},borders:{top:nb(),bottom:nb(),left:nb(),right:nb()},margins:{top:140,bottom:140,left:200,right:200},width:{size:rw,type:WidthType.DXA},children:rightK}),
    ]})]
  });
}
function statBox(label,value,sub,fill=LT_BLUE,accent=NAVY) {
  return new TableCell({
    shading:{fill,type:ShadingType.CLEAR},borders:none,
    margins:{top:140,bottom:140,left:160,right:160},width:{size:2340,type:WidthType.DXA},
    children:[
      p([r(label,{bold:true,size:17,color:accent})],{alignment:AlignmentType.CENTER}),
      p([r(value,{bold:true,size:30,color:accent})],{alignment:AlignmentType.CENTER,spacing:{before:40,after:20}}),
      p([r(sub,{size:17,color:MID,italics:true})],{alignment:AlignmentType.CENTER}),
    ]
  });
}

// ════════════════════════════════════════════════════════════════════════════
const doc = new Document({
  numbering:{config:[
    {reference:"bullets",levels:[{level:0,format:LevelFormat.BULLET,text:"\u2022",alignment:AlignmentType.LEFT,style:{paragraph:{indent:{left:720,hanging:360}}}}]},
    {reference:"numbers",levels:[{level:0,format:LevelFormat.DECIMAL,text:"%1.",alignment:AlignmentType.LEFT,style:{paragraph:{indent:{left:720,hanging:360}}}}]},
  ]},
  styles:{default:{document:{run:{font:"Arial",size:20,color:DARK}}}},
  sections:[{
    properties:{page:{size:{width:12240,height:15840},margin:{top:1008,right:1152,bottom:1008,left:1152}}},
    children:[

      // ── COVER ──────────────────────────────────────────────────────────────
      box([
        p([r("OPINCAR MACHINERY",{bold:true,size:22,color:"7FA8C9"})],{alignment:AlignmentType.CENTER,spacing:{before:0,after:80}}),
        p([r("Condition Intelligence Reports",{bold:true,size:44,color:WHITE})],{alignment:AlignmentType.CENTER}),
        p([r("Service Launch & Client Acquisition Guide",{size:24,color:"AAC8E8",italics:true})],{alignment:AlignmentType.CENTER,spacing:{before:80,after:60}}),
        p([r("How to Add a 10\u201315% Price Premium to Every Machine Opincar Sells \u2014 With Minimal Extra Work",{size:20,color:"7FA8C9"})],{alignment:AlignmentType.CENTER}),
      ],NAVY,none,{top:280,bottom:280,left:360,right:360}),

      sp(120),

      // ── WHAT THIS IS ───────────────────────────────────────────────────────
      new Table({
        width:{size:9360,type:WidthType.DXA},columnWidths:[2340,2340,2340,2340],
        rows:[new TableRow({children:[
          statBox("PRICE PREMIUM","10\u201315%","on every machine sold",LT_GRN,GREEN),
          statBox("EXTRA WORK","Minimal","Photos + AI + 25 yrs knowledge",LT_BLUE,STEEL),
          statBox("REPORT TIME","48 Hrs","from intake to delivery",LT_GOLD,GOLD),
          statBox("ALSO SELLS","$400\u2013$800","as standalone 3rd-party report",LT_TEAL,TEAL),
        ]})]
      }),

      sp(80),
      box([
        p([r("The core idea is simple:",{bold:true,size:22,color:NAVY})],{alignment:AlignmentType.CENTER}),
        sp(60),
        p([r("Right now, when Opincar lists a used CNC machine for sale, a buyer looks at the photos, reads the specs, and either trusts the listing or doesn\u2019t. Most used equipment buyers are uncertain, and uncertainty kills deals or forces price concessions. The Condition Intelligence Report eliminates that uncertainty. It is a branded, professional assessment of every machine Opincar sells \u2014 condition score, market comparables, part availability, appraiser notes. Buyers pay more when they know exactly what they are buying. That premium more than covers the time to produce the report, and the report itself becomes a sellable product to outside buyers who are evaluating machines from any dealer.",{size:20,color:DARK})],{alignment:AlignmentType.CENTER}),
      ],LT_GOLD,{top:sb(GOLD,4),bottom:sb(GOLD,4),left:sb(GOLD,4),right:sb(GOLD,4)},{top:180,bottom:180,left:280,right:280}),

      sp(120),

      // ── PART 1: THE BUSINESS CASE ──────────────────────────────────────────
      divider(),
      sectionHeader("PART 1:  THE BUSINESS CASE \u2014 WHY THIS WORKS"),
      sp(80),

      p([r("Before building anything, TJ needs to understand why buyers pay more for a machine with a Condition Intelligence Report attached. The psychology is straightforward.",{size:20,color:DARK})]),
      sp(80),

      twoCol([
        p([r("WHY BUYERS PAY A PREMIUM",{bold:true,size:19,color:NAVY})],{spacing:{before:0,after:60}}),
        p([r("Used machinery buyers face three fears: hidden mechanical problems they can\u2019t see, control systems nearing end-of-life, and paying more than the machine is worth. All three fears cost the buyer real money if they get it wrong. A Condition Intelligence Report directly addresses all three.",{size:19,color:DARK})]),
        sp(60),
        bul("It signals that Opincar stands behind the machine\u2019s condition",GREEN,true),
        bul("It gives buyers the confidence to act faster and not negotiate as hard",GREEN,true),
        bul("It provides data that buyers can show to their own management, lender, or CFO to justify the purchase",GREEN,true),
        bul("It positions Opincar as a professional operation, not just a yard",GREEN,true),
        sp(60),
        p([r("The result: buyers who see a CIR on a listing convert faster, negotiate less, and pay a documented premium.",{size:19,color:DARK,bold:true})])
      ],[
        p([r("THE MATH",{bold:true,size:19,color:NAVY})],{spacing:{before:0,after:60}}),
        new Table({
          width:{size:4280,type:WidthType.DXA},columnWidths:[2400,1880],
