const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, BorderStyle, WidthType, ShadingType, LevelFormat,
} = require('docx');
const fs = require('fs');

// ── COLOR PALETTE ─────────────────────────────────────────────────────────────
const NAVY    = "1B2B4B";
const STEEL   = "2A5F8F";
const GOLD    = "B8842A";
const GREEN   = "1A5C36";
const TEAL    = "0D5C63";
const ORANGE  = "B85C1A";
const LT_BLUE = "DAE8F5";
const LT_GRN  = "D5EEE0";
const LT_GOLD = "FAF0DC";
const LT_TEAL = "D4EDEE";
const LT_ORNG = "FAEADA";
const LT_GRAY = "F3F4F6";
const WHITE   = "FFFFFF";
const DARK    = "1E2A35";
const MID     = "445566";

// ── BORDER HELPERS ────────────────────────────────────────────────────────────
const nb  = () => ({ style: BorderStyle.NONE, size: 0, color: "FFFFFF" });
const sb  = (c="BBBBBB", sz=1) => ({ style: BorderStyle.SINGLE, size: sz, color: c });
const none  = { top: nb(), bottom: nb(), left: nb(), right: nb() };
const allgr = { top: sb(), bottom: sb(), left: sb(), right: sb() };
const tbot  = (c="CCCCCC") => ({ top: sb(c), bottom: sb(c), left: nb(), right: nb() });

// ── ELEMENT FACTORIES ─────────────────────────────────────────────────────────
function r(text, o={}) {
  return new TextRun({ text, font: "Arial", ...o });
}
function p(children, o={}) {
  const kids = Array.isArray(children) ? children : [r(children, { size: 20, color: DARK })];
  return new Paragraph({ children: kids, ...o });
}
function sp(sz=80) { return p([r("")], { spacing: { before: sz, after: sz } }); }

function bul(text, color=DARK, bold=false, sz=20) {
  return new Paragraph({
    numbering: { reference: "bullets", level: 0 },
    spacing: { before: 50, after: 50 },
    children: [r(text, { size: sz, color, bold })]
  });
}
function subbul(text, color=MID) {
  return new Paragraph({
    numbering: { reference: "subbullets", level: 0 },
    spacing: { before: 40, after: 40 },
    children: [r(text, { size: 18, color, italics: true })]
  });
}

function divider(color=STEEL) {
  return new Paragraph({
    border: { bottom: { style: BorderStyle.SINGLE, size: 8, color, space: 4 } },
    spacing: { before: 180, after: 60 },
    children: [r("")]
  });
}

function box(kids, fill, borders, pad={top:160,bottom:160,left:240,right:240}) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [new TableRow({ children: [new TableCell({
      shading: { fill, type: ShadingType.CLEAR },
      borders,
      margins: pad,
      width: { size: 9360, type: WidthType.DXA },
      children: Array.isArray(kids) ? kids : [kids]
    })]})]
  });
}

function sectionHead(text, fill=NAVY, textColor=WHITE) {
  return box(
    [p([r(text, { bold: true, size: 24, color: textColor })])],
    fill, none, { top: 120, bottom: 120, left: 240, right: 240 }
  );
}

function stepBox(num, title, bodyItems, accent=NAVY) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [720, 8640],
    rows: [new TableRow({ children: [
      new TableCell({
        shading: { fill: accent, type: ShadingType.CLEAR },
        borders: none,
        margins: { top: 120, bottom: 120, left: 120, right: 120 },
        width: { size: 720, type: WidthType.DXA },
        children: [p([r(num, { bold: true, size: 28, color: WHITE })], { alignment: AlignmentType.CENTER })]
      }),
      new TableCell({
        shading: { fill: LT_BLUE, type: ShadingType.CLEAR },
        borders: { top: nb(), bottom: sb("AAAAAA"), left: nb(), right: nb() },
        margins: { top: 120, bottom: 120, left: 200, right: 200 },
        width: { size: 8640, type: WidthType.DXA },
        children: [
          p([r(title, { bold: true, size: 22, color: accent })], { spacing: { before: 0, after: 60 } }),
          ...bodyItems
        ]
      })
    ]})]
  });
}

function scriptBox(label, script) {
  return box([
    p([r(label, { bold: true, size: 17, color: TEAL })]),
    sp(40),
    p([r(script, { size: 20, color: DARK, italics: true })]),
  ], LT_TEAL, { top: sb(TEAL, 4), bottom: sb("AAAAAA"), left: sb(TEAL, 4), right: sb("AAAAAA") },
  { top: 160, bottom: 160, left: 240, right: 240 });
}

function calRow(trigger, action, accent, i) {
  const fill = i % 2 === 0 ? LT_BLUE : WHITE;
  return new TableRow({ children: [
    new TableCell({
      shading: { fill, type: ShadingType.CLEAR }, borders: tbot(),
      margins: { top: 80, bottom: 80, left: 160, right: 160 },
      width: { size: 2200, type: WidthType.DXA },
      children: [p([r(trigger, { bold: true, size: 19, color: accent })], { alignment: AlignmentType.CENTER })]
    }),
    new TableCell({
      shading: { fill, type: ShadingType.CLEAR }, borders: tbot(),
      margins: { top: 80, bottom: 80, left: 160, right: 160 },
      width: { size: 7160, type: WidthType.DXA },
      children: [p([r(action, { size: 19, color: DARK })])]
    })
  ]});
}

// ════════════════════════════════════════════════════════════════════════════════
const doc = new Document({
  numbering: { config: [
    { reference: "bullets", levels: [{ level: 0, format: LevelFormat.BULLET, text: "\u2022",
        alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 720, hanging: 360 } } } }] },
    { reference: "subbullets", levels: [{ level: 0, format: LevelFormat.BULLET, text: "\u25E6",
        alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 1080, hanging: 360 } } } }] },
  ]},
  styles: { default: { document: { run: { font: "Arial", size: 20, color: DARK } } } },
  sections: [{ properties: { page: { size: { width: 12240, height: 15840 }, margin: { top: 1008, right: 1152, bottom: 1008, left: 1152 } } }, children: [

    // ── COVER ──────────────────────────────────────────────────────────────────
    box([
      p([r("OPINCAR MACHINERY  \u00B7  SMYRNA, TN", { bold: true, size: 18, color: "6E9BB8" })], { alignment: AlignmentType.CENTER, spacing: { before: 0, after: 80 } }),
      p([r("Condition Intelligence", { bold: true, size: 48, color: WHITE })], { alignment: AlignmentType.CENTER }),
      p([r("Reports", { bold: true, size: 48, color: GOLD })], { alignment: AlignmentType.CENTER, spacing: { before: 0, after: 80 } }),
      p([r("Service Launch & Client Acquisition Guide", { bold: true, size: 24, color: "AAC8E4" })], { alignment: AlignmentType.CENTER, spacing: { before: 0, after: 60 } }),
      p([r("How to add a 10\u201315% price premium to every machine Opincar sells \u2014 and turn that expertise into a standalone revenue stream.", { size: 20, color: "7FA8C4", italics: true })], { alignment: AlignmentType.CENTER }),
    ], NAVY, none, { top: 300, bottom: 300, left: 400, right: 400 }),

    sp(80),

    // ── QUICK STATS ───────────────────────────────────────────────────────────
    new Table({
      width: { size: 9360, type: WidthType.DXA },
      columnWidths: [2340, 2340, 2340, 2340],
      rows: [new TableRow({ children: [
        ...[
          ["+10\u201315%", "price premium on\nexisting inventory", NAVY, LT_BLUE],
          ["$400\u2013$800", "per standalone\nreport sold", GREEN, LT_GRN],
          ["90 min", "average time to\nproduce one report", TEAL, LT_TEAL],
          ["~$0", "additional inventory\nrequired", GOLD, LT_GOLD],
        ].map(([val, label, accent, fill]) => new TableCell({
          shading: { fill, type: ShadingType.CLEAR }, borders: none,
          margins: { top: 120, bottom: 120, left: 80, right: 80 },
          width: { size: 2340, type: WidthType.DXA },
          children: [
            p([r(val, { bold: true, size: 36, color: accent })], { alignment: AlignmentType.CENTER }),
            p([r(label, { size: 17, color: MID })], { alignment: AlignmentType.CENTER, spacing: { before: 40 } }),
          ]
        }))
      ]})]
    }),

    sp(80),

    box([
      p([r("The core idea in one sentence:", { bold: true, size: 20, color: NAVY })]),
      sp(40),
      p([r("Every used machine Opincar sells already carries TJ\u2019s 25+ years of expert knowledge inside it. The Condition Intelligence Report packages that knowledge into a branded, credentialed document \u2014 one that buyers trust, pay more for, and refer others to. No new inventory. No new overhead. Just more money on every machine already in the yard.", { size: 20, color: DARK })]),
    ], LT_GOLD, { top: sb(GOLD, 4), bottom: sb(GOLD, 4), left: sb(GOLD, 4), right: sb(GOLD, 4) },
    { top: 160, bottom: 160, left: 240, right: 240 }),

    sp(100),

    // ══════════════════════════════════════════════════════════════════════════
    divider(GREEN),
    sectionHead("PART 1:  THE BUSINESS CASE \u2014 WHY BUYERS PAY A PREMIUM", GREEN),
    sp(80),

    p([r("Used machinery buyers face three fears before they wire money on a machine they\u2019ve never seen in person:", { size: 20, color: DARK })]),
    sp(60),

    new Table({
      width: { size: 9360, type: WidthType.DXA },
      columnWidths: [3120, 3120, 3120],
      rows: [new TableRow({ children: [
        ...[
          ["FEAR 1", "Hidden Mechanical Problems", "Spindle wear, way damage, hydraulic leaks, toolchanger issues \u2014 things that look fine in a listing photo but cost $5,000\u2013$40,000 to fix.", NAVY, LT_BLUE],
          ["FEAR 2", "Control System Risk", "An end-of-life Fanuc or Siemens control can cost $15,000\u2013$60,000 to replace. Sellers don\u2019t always disclose this. Buyers often don\u2019t know to ask.", TEAL, LT_TEAL],
          ["FEAR 3", "Overpaying", "Without current market comparables, a buyer has no way to know if $95,000 for a 2012 Okuma is fair, high, or a bargain. Uncertainty leads to lower offers or no offer.", ORANGE, LT_ORNG],
        ].map(([tag, title, body, accent, fill]) => new TableCell({
          shading: { fill, type: ShadingType.CLEAR }, borders: none,
          margins: { top: 140, bottom: 140, left: 180, right: 180 },
          width: { size: 3120, type: WidthType.DXA },
          children: [
            p([r(tag, { bold: true, size: 17, color: accent })], { alignment: AlignmentType.CENTER }),
            p([r(title, { bold: true, size: 21, color: DARK })], { alignment: AlignmentType.CENTER, spacing: { before: 40, after: 80 } }),
            p([r(body, { size: 19, color: DARK })]),
          ]
        }))
      ]})]
