function r(text, o={}) {
  return new TextRun({ text, font: "Arial", ...o });
}
function p(children, o={}) {
  const kids = Array.isArray(children) ? children : [r(children, { size: 20, color: DARK })];
  return new Paragraph({ children: kids, ...o });
}
function sp(sz=80) { return p([r("")], { spacing: { before: sz, after: sz } }); }

function bul(text, color=DARK, bold=false, sz=20) {
  return new Paragraph({
    numbering: { reference: "bullets", level: 0 },
    spacing: { before: 50, after: 50 },
    children: [r(text, { size: sz, color, bold })]
  });
}
function subbul(text, color=MID) {
  return new Paragraph({
