          margins: { top: 120, bottom: 120, left: 80, right: 80 }, width: { size: 2340, type: WidthType.DXA },
          children: [
            p([r(val, { bold: true, size: val.length > 8 ? 26 : 32, color: accent })], { alignment: AlignmentType.CENTER }),
            p([r(label, { size: 17, color: MID })], { alignment: AlignmentType.CENTER, spacing: { before: 40 } }),
          ]
        }))
